/** Harikathamrutasara sandhis 11–20: meanings (ta). */
export const taHks2: MeaningPack = {
  lang: 'ta',
  texts: {
    'harikathamrutasara-11': {
      summary: "பதினோராம் சந்தி (தியானப் பிரக்ரியை): ஜீவன் ஹரிக்கு உட்பட்டவன், ஹரி எல்லாவற்றுக்கும் உள்ளிருந்து தூண்டுபவன் என்பதால் புலன்களிலும் உடல் நாடிகளிலும் ஒவ்வொரு செயல்-அனுபவத்திலும் அவனை எவ்வாறு நினைக்க வேண்டும் என்று இச்சந்தி கூறுகிறது. புலன்கள், சுவைகள், உயிர்கள், ஆண்-பெண்களின் அபிமான தேவதைகளில் அவன் வடிவங்களை விளக்கி, இருவகை வழிபாட்டைப் போதிக்கிறது: வியதிரேகம் (பொருள்களை அவனிடமிருந்து வேறாக அர்ப்பணித்தல்), அன்வயம் (ஒவ்வொரு பொருளிலும் அவனைக் காணுதல், பிம்பத்தை மறக்காதிருத்தல்). விக்ரஹம், உயிர்கள், இயற்கை மலைகளில் வழிபாட்டைக் கூறி, ஹரி சராசரங்களில் முழுமையாக வியாபித்திருப்பதை அறியாதவர்களுக்கு தீர்த்த யாத்திரை, நீராடல், ஜபம், தானம் ஆகியவற்றால் பயனில்லை என்று முடிக்கிறது.",
      verses: {
        '0.0': "குருவின் கருணையால் ஹரிகதாம்ருத ஸாரத்தைக் கூறுகிறேன்; உயர்ந்த பகவத் பக்தர்களே, இதை மரியாதையுடன் கேளுங்கள். (ஒவ்வொரு சந்தியின் தொடக்கத்திலும் பாடப்படும் பல்லவி.)",
        '0.1': "செருப்பிலுள்ள முள், மணல் முதலியவை நாளும் நடப்பவனை வருத்துவது போல பதினொரு புலன்களின் பாவங்களும் வருத்துகின்றன; ஆனால் பதினொரு புலன்களிலும் ஹ்ருஷீகேசனின் வடிவை விடாமல் பக்தியுடன் நினைப்பவன் எத்தனை குற்றங்கள் செய்தாலும் பாவக் குவியல்கள் அவன் முக்தி வழியைத் தடுக்கா. (இப்பாடலின் பாடம் முழுமையாகச் சரிபார்க்கப்படவில்லை.)",
        '0.2': "பகலிலும் அணையாத நந்தா விளக்கு போல வேதத்தால் அறியப்படுபவனைக் கைகூப்பி வழிபடு; நான்கு புருஷார்த்தங்களில் ஒன்றையும் கேட்காதே; ஜகத்துதரன் அளித்ததை உண்; பிராணன், புலன்கள், மனம் முதலியவை இறைவனின் அதீனம் என்று அடிக்கடி நினைத்துக்கொண்டிரு.",
        '0.3': "ஜீவன் சுதந்திரமற்றவன்; ஹரி ஒருவனே முழுச் சுதந்திரன், நித்திய சுகமயன். ஜீவன் ஏழை, கட்டுண்டவன், சிறிதளவு அறிவும் ஆற்றலும் உடையவன், துயருறுபவன், சிறியவன்; உடல் கொண்ட அவனுக்கு ஒரு தலைவன் இருக்கிறான்; ஹரி உலகெங்கும் நிறைந்தவன், செய்பவன், பிரம்மா முதலிய தேவர்களால் துதிக்கப்படும் பிரம்மம்; இவ்வாறு அவனைப் போற்று.",
        '0.4': "விஸ்வன் முதலிய எட்டு வடிவங்களை ஒன்பதால் பெருக்கினால் எழுபத்திரண்டு வடிவங்களாகின்றன, ஒவ்வொன்றும் ஆயிரம் எண்ணிக்கையுடையது; தனித்தனி நாடிகளில் சர்வோத்தமனை அறிவாயாக என்று பீஷ்மர் சாந்தி பர்வத்தில் தர்மபுத்திரனுக்கு உபதேசித்தார்.",
        '0.5': "எட்டு பிரகிருதிகளுக்குள் விஸ்வன் முதலிய எட்டு வடிவங்களால் இருந்து பக்தர்களின் முட்களை நீக்கித் தினமும் காக்கிறான்; விடாத உறவினன் போல வைகுண்டரமணன் தன்னவர்களை முள்ளற்ற நல்ல வழியில் நடத்துகிறான்; தீயவர்களை அடிக்கிறான்.",
        '0.6': "சக்தி முதலிய வடிவங்களால் புலன்களின் அபிமானிகளுக்குள் உறைந்து, அறியாதவர்களுக்கு எட்டாதவனான ஸ்வரமணன் ஸ்தூல விஷயங்களை நாளும் அனுபவிக்கிறான்; இதை அறியாமல் 'நான் அனுபவிக்கிறேன்' என்பவர்கள் நிச்சயமாக நரகங்களையே அனுபவிக்கிறார்கள்; மீண்டும் மீண்டும் பிறவிக் காட்டில் அலைந்து சோர்கிறார்கள்.",
        '0.7': "சுருசி, ருசிர, சுகந்த, சுசி என்ற பெயர்களால் ஆறு சுவைகளில் பன்னிரு வடிவங்களால் ஸ்ரீ-பூ-துர்கையருடன் இருக்கிறான்; எழுபத்தீராயிரம் வாயு வடிவங்களில் மகா பராக்கிரம கர்த்தாவாக நாடிகளுக்குள் இருக்கிறான்.",
        '0.8': "(இறைவனிடம்:) உன்னை எங்கும் நினைப்பவர்கள் செய்யும் பிற செயல்களும் புண்ணியச் செயல்களே, ஐயமில்லை. உன்னை நினையாமல் நீராடல், ஜபம், ஹோமம், அன்னம், ஆடை, யானை, குதிரை, நிலம், செல்வம், தானியம் முதலிய எல்லா தர்மங்களும் செய்தால் பயன் என்ன?",
        '0.9': "விரும்பத்தக்க அனுபவப் பொருள்களில் ஷிபிவிஷ்டன் என்ற பெயரால் தினமும் எல்லா உயிர்களையும் திருப்தி செய்து தானும் நிறைவுற்று, வயிற்றில் உறைந்து புலன்களுக்குச் சாரமான வளர்ச்சி அளித்து, எல்லோருக்கும் பிரியனாய் உயிர்களுக்குத் தெரியாமல் எல்லா விஷயங்களையும் உண்கிறான்.",
        '0.10': "'காரகன்' என்ற பெயருடன் ஞான-கர்மங்களைத் தூண்டுபவனாய் கர்மேந்திரியங்களின் அதிபதிகளுக்குள் உறைந்து செயல்களைக் காட்டுகிறான்; முக்குணமயமான பொருள்களிலுள்ள வடிவங்களின் பெயரால் அழைக்கப்படுகிறான்; தன்னை வெளிக்காட்டாமல் மக்களை மயக்கும் மோகத்தை உண்டாக்குபவன்.",
        '0.11': "பூதங்களில் 'த்ரவ்யன்' எனவும், கர்மேந்திரியங்களில் அழிவற்றவன் எனவும், ஞானேந்திரியங்களில் நற்செயலுடையவன் எனவும் இருக்கிறான்; துதிக்கத்தக்க கர்த்தா, சுகமயன், உலகில் சேவிக்கப்படுபவனும் சேவிப்பவனும் எனப்பட்டு அரணிக் கட்டையிலுள்ள நெருப்பு போல இருக்கிறான்.",
        '0.12': "மனம் முதலிய புலன்களில் வாயுதேவன் 'சுசி' எனப்பட்டு எப்போதும் நிலைத்திருக்கிறான், 'சுசிஷத்ஹோதா' என்று அழைக்கப்படுகிறான்; வாமன-ஹ்ருஷீகேச வடிவங்களால் ஹரி எப்போதும் உடலுக்குள் இருந்து விஷயத்தால் பிறக்கும் இன்பத்தை உயிர்களுக்கு அனுபவிக்கச் செய்கிறான்.",
        '0.13': "தூண்டுபவர்களிலும் தூண்டப்படுபவர்களிலும் ஹரி தானே இருந்து, பகையின்றித் தன் பெயர்-உருவத்தால் எல்லோரையும் தூண்டுகிறான்; தன்னைக் காட்டிக்கொள்ளாமல் எல்லாருக்குள்ளும் இருந்து, கங்கையின் தந்தை எல்லாச் செயல்களையும் தானே செய்து செய்வித்துப் பார்த்துச் சிரிக்கிறான்.",
        '0.14': "ஹரியே முதன்மை இயக்குநர் என்று அறிந்து, புண்ணிய-பாவம், மகிழ்ச்சி-சினம், லாபம்-நஷ்டம், சுகம்-துக்கம் போன்ற இருமைகளை நரகம், பூமி, சுவர்க்கம், முக்தி ஆகியவற்றில் அவன் திருவடிக்குச் சமர்ப்பித்து, புலன்களை இயக்குபவனை எங்கும் நினைத்தபடி இரு.",
        '0.15': "சிறுவன் பலனை எண்ணாமல் தன் விருப்பப்படி செய்து தினமும் மகிழ்வது போல, ஞானத்துடன் விதி-தடைகளைக் கவலையுடன் நோக்காமல் செயல்களைச் செய்; கர்மத்தில் முதன்மையான புருஷேசனிடம் பக்தியை வேண்டு, போற்று.",
        '0.16': "இழப்பு, ஆதாயம், வெற்றி, தோல்வி எதை அளித்தாலும் அனுபவித்து, தினமும் லக்ஷ்மிநிவாசனின் கருணையையே சம்பாத்தியமாகக் கருது; கருணையுள்ள அவன் உடலின் உறவினர் போல உள்ளும் புறமும் இருந்து, ஞானானந்தமயரான தன்னவர்களைப் பேரன்புடன் காக்கிறான்.",
        '0.17': "அந்த பரமன் எல்லாப் புலன்களிலும் வியாபித்து, எல்லா உயிர்களிலும் தெரிவிக்காமல் விஷயங்களை ஏற்கிறான்; பாவமற்ற புராண புருஷன் அருகிருந்து, பல வடிவங்களைத் தாங்கி, தன்னைக் காட்டிக்கொள்ளாமல் செயல்களைச் செய்கிறான்.",
        '0.18': "வானில் செல்வன, நிலத்தில் திரிவன, நீரில் வாழ்வன, இரவில் அலைவன ஆகியவற்றுக்குள் இருந்து அவற்றின் செயல்களைச் செய்கிறான்; பெருமகிமையுடையவனும் மிக நுண்ணியவனுமான அவன் மனத்தில் எத்தனை வகையாக எண்ணினாலும் புலன்களுக்கு விஷயமாவதில்லை; கீசகாரியான (பீமனுக்கு) பிரியன், கவிகள் பாடும் மகாராயன்.",
        '0.19': "ஒரே கோத்திர-பிரவரம் உடையவர்கள் சந்தியாவந்தனம் செய்து, இறுதியில் மக்கள் தத்தம் பெயர்களைப் பெறுவது போல, ஒரே உடலில் இருந்து இகழத்தக்க-இகழத்தகாத செயல்களைச் செய்து செய்வித்து, இந்திரேசன் எல்லா உயிர்களுக்குள்ளும் 'ஈசன்' எனப்படுகிறான்.",
        '0.20': "துருப்பிடித்த இரும்பைத் தீயில் சுட்டுத் தூய்மையாக்குவது போல, நெல்லிலுள்ள அரிசியை இறுதியில் உமியிலிருந்து பிரிப்பது போல, தன்னை மறந்து உரத்த சிரிப்புடன் ஒருமுறை 'விட்டலா!' என்று அழைத்தால் அவன் பாவங்களை ஓட்டி விடுவித்து, அவனைத் தன்னுள் வைத்துக் காக்கிறான்.",
        '0.21': "கடலில் நீர்வாழ் உயிர்கள் தம் விருப்பப்படி தத்தம் இடங்களில் மகிழ்ந்து திரிவது போல, தாமரை நாபனுக்குள் பிரம்மா, சிவன், இந்திரன் முதலிய பல உயிர்க்கூட்டங்கள் எப்போதும் வாழ்கின்றன.",
        '0.22': "வாஸுதேவன் உள்ளும் புறமும் ஒளிர்விப்பவனாய் பிம்பமாக அந்தந்த உருவம்-பெயரில் எங்கும் பிரகாசிக்கிறான்; 'சமன்வயம்' (ஒவ்வொரு பொருளிலும் அவனைக் காணுதல்) எனப்படும் இந்த நல்லுபாசனையைச் செய்பவன் முக்தி நாடுவோருள் சிறந்தவன்; அவன் இப்பூமியில் ஜீவன்முக்தன்.",
        '0.23': "அனுபவப் பொருள்களில் ஏற்ற-ஏற்காத சுவைகளை அறிந்து, ஏற்றவர்-ஏற்காதவர் அனைவரிடமும் உறையும் ஹரிக்கு தினமும் சமர்ப்பி; செல்வம் அல்லது வறுமை வந்தபோது பூரிக்காமல், குன்றிச் சோராமல், நற்பக்தி-வைராக்கியம்-ஞானத்தை வேண்டு; நீ துர்ப்பாக்கியசாலி எனப்படாதே.",
        '0.24': "நிலம், நீர், மலைகளில் விளையும் பழம், நல்ல மலர்கள், மணம், சாறு, ஸ்ரீதுளசி முதலிய எல்லா பூஜைப் பொருள்களையும் கங்கையின் தந்தைக்கு பலவகையாக நாளும் அர்ப்பணிப்பதை அறிஞர்கள் 'வியதிரேக பூஜை' (பொருள்களை அவனிடமிருந்து வேறாக அர்ப்பணித்தல்) என்கிறார்கள்.",
        '0.25': "ஸ்ரீகரனை எங்கும் கண்டு, குணம்-உருவம்-செயல்களை அவனுடையவை எனக் கண்டு, வியதிரேகத்தை மட்டும் அறிந்து நின்றுவிடாமல், பிம்பனை மறக்காமல் அன்வயம் செய் (ஒவ்வொரு பொருளிலும் அவனைக் காண்); கருணையுள்ளவன் மறுக்காமல் அருளுடன் ஏற்று, பக்தர்களின் துயரங்களை நீக்கி சுகம் அளித்து இடைவிடாமல் காக்கிறான்.",
        '0.26': "வியதிரேகம், அன்வயம் எனப்படும் இந்த பூஜை முறைகளை அறிந்து தேவேசனை இடைவிடாமல் திருப்தி செய்தபடி இரு; பெருமகிமையுடையவன் இதை ஏற்று நிலை-மரணம்-பிறவிகளை நீக்கி, சேவகர்களைத் தன்னுள் வைத்து மகிழ்விக்கும் பக்தவத்சலன்.",
        '0.27': "தாமரை நாபனுக்குப் பூமியில் ஜடம், சேதனம் என இருவகைச் சிலைகள் உள்ளன; சேதனத்தில் ஆண்-பெண் என இரண்டு; ஜடத்தில் மனிதர் நிறுவிய விக்ரஹம், இயற்கை மலைகள் என இரண்டு என்று அறி; பிரதீகத்தில் பதினைந்தின் அழகிய தொகுப்பை அறிந்து வழிபட்டுவா. (இறுதி வரி தெளிவற்றது.)",
        '0.28': "பிரம்மா, வாயு, இந்திரன், சிவன், நாகேசன், ஸ்மரன், அகங்கார அதிபதி, பிராணன் முதலியோர் ஆண்களின் உடல்களின் அபிமானிகளாகி, தன்னைக் காட்டிக்கொள்ளாத, குற்றமற்ற அநிருத்த நாராயணனின் வடிவை வழிபட்டுச் சுகம் அளிக்கிறார்கள்.",
        '0.29': "ஸ்ரீ, சரஸ்வதி, பாரதி, சௌபர்ணி, வாருணி, பார்வதி முதலியோர் பெண்களுக்குள் அபிமான தேவியர்; அருண வண்ணமுள்ள ஸங்கர்ஷண-ப்ரத்யும்ன வடிவங்களை இரவும் பகலும் உபாசித்து மகிழ்கிறார்கள்.",
        '0.30': "நிறுவப்பட்ட பிரதீகங்களில் (பிரதிஷ்டை செய்த விக்ரஹங்களில்) பார்கவன், அக்னி, வாயு முதலிய தேவர்கள் அபிமானிகளாக நிலைத்து துதிக்கப்பட்டு, தினமும் துளசி, சந்தனம், அட்சதை, மலர், பழம், தீபம், பஞ்சாமிர்தத்தால் வழிபடும் பக்தர்களுக்குப் புருஷார்த்தங்களை அளிக்கிறார்கள்.",
        '0.31': "இயற்கை மலைகளின் அபிமான தேவர்கள் தம் தலைவனான ஸ்ரீவாஸுதேவனை வழிபடுகிறார்கள்; உள்ளார்ந்த பேதம் அற்றவனை நான்கு வகை பிரதீகங்களில் அறிந்து வழிபட்டால் பிறவிக் கடலைக் கடக்கச் செய்து முக்தர்களாக்குகிறான்.",
        '0.32': "எந்த க்ஷேத்திரத்துக்குச் சென்றால் என்ன? எந்தத் தீர்த்தத்தில் மூழ்கினால் என்ன? எந்த ஜபம், தவம், ஹோமம், தானம் செய்தால் என்ன பயன், ஸ்ரீவர ஜகந்நாத விட்டலன் இந்தச் சராசர உயிர்களுக்குள் முழுமையாக நிறைந்திருக்கிறான் என்று அறியாத மனிதர்களுக்கு.",
      },
    },
    'harikathamrutasara-12': {
      summary: "பன்னிரண்டாம் சந்தி (நாடீ பிரகரணம்): உடலில் எழுபத்தீராயிரம் நுண் நாடிகள் உள்ளன, ஒவ்வொரு பக்கமும் முப்பத்தாறாயிரம், நூறு ஆண்டுகளின் பகல்-இரவுகள் அளவு; அவற்றில் ஹரி லக்ஷ்மியுடன் எண்ணற்ற வடிவங்களில் இருந்து, பிரம்மா, வாயு, அந்தந்த அபிமான தேவர்களின் சேவையை ஏற்கிறான். புண்ணிய நதிகள் இந்நாடிகளில் பாய்கின்றன, ஞானிகள் அங்கே நாளும் நீராடுகிறார்கள். அறிந்தவன் செய்வதெல்லாம் ஹரி பூஜை, ஹரி எல்லா உயிர்களிலும் இருந்தும் அவற்றின் குற்றங்கள் தீண்டாதவன் என்று இச்சந்தி போதிக்கிறது; நூற்றுப்பதினாறு ஆண்டு வாழ்க்கையை மூன்று ஸவனங்களின் யாகமாக வர்ணிக்கிறது; வாயுதேவன் ஹம்ஸ மந்திர ஜபமாகச் செய்யும் மூச்சுகளை எண்ணுகிறது; இறைவன் பேச வைத்தபடியே பேசினேன் என்ற கவியின் கூற்றுடன் முடிகிறது.",
      verses: {
        '0.0': "குருவின் கருணையால் ஹரிகதாம்ருத ஸாரத்தைக் கூறுகிறேன்; உயர்ந்த பகவத் பக்தர்களே, இதை மரியாதையுடன் கேளுங்கள். (ஒவ்வொரு சந்தியின் தொடக்கத்திலும் பாடப்படும் பல்லவி.)",
        '0.1': "வாஸுதேவன் பிராணன் முதலிய தத்துவ அதிபதிகளின் சேவையை ஏற்று, இவ்வுடலிலுள்ள முப்பத்தாறாயிரம் நல்ல நாடிகளுக்குள் ஸ்ரீ, பூமி தேவியருடன் விளையாடுகிறான்; அந்தப் பரமேசனின் தூய அழகிய வடிவங்களைச் சிந்தித்து மகிழ்ந்திரு.",
        '0.2': "கால்களில் பன்னிரண்டாயிரம், நடு உடலில் பதினான்காயிரம், கைகளில் நான்காயிரம், தலையில் ஆறாயிரம் நாடிகள் உள்ளன. இவ்வாறு சிந்தித்து, இரவு-பகலின் அபிமான தேவர்களை அறிந்து உபாசிப்பவர்கள் பூமியில் இருந்தும் சுவர்க்கவாசிகளே.",
        '0.3': "'ப்ருஹதி' என்ற பெயருடைய, குற்றமற்ற வாஸுதேவன் ஆண்-பெண்களின் எழுபத்தீராயிரம் நாடிகளில் இருந்து, பிரம்மா முதலிய தேவகணங்களால் போற்றப்பட்டு, பெருமகிமையும் பெருங்கருணையும் உடையவனாய் எல்லா உயிர்களையும் இடைவிடாமல் காக்கிறான்.",
        '0.4': "நூறு ஆண்டுகளுக்கு முப்பத்தாறாயிரம் நாள்கள்; உடலில் நாடிகளும் அவ்வளவே என்று அறிந்து ஒரு நாள் அறிஞர்களைப் போற்றியவன் ஒவ்வொரு நாளும் தம்பதிகளின் அர்ச்சனையைச் செய்தவனே; இது உண்மை, ஒருபோதும் ஐயமில்லை.",
        '0.5': "இருபத்துநான்கு தத்துவங்களும் அவற்றின் அதிபதிகளான பிரம்மா முதலிய தேவர்களும் தினமும் ஒவ்வொரு நாடியிலும் இருந்து, பதினான்கு உலகங்களிலும் உயிர்த் தொகுதிகளைக் காக்கும் நிலையானவனை அந்தந்த இடத்தில் கண்டு மகிழ்கிறார்கள்.",
        '0.6': "சத்திய சங்கல்பனான ஹரி எழுபத்தீராயிரம் நாடிகளில் 34,56,000 வடிவங்களால் சித்-பிரகிருதியுடன் (லக்ஷ்மியுடன்) இருக்கிறான்; பரம நித்திய மங்கல மூர்த்தியான அவன் பக்தர்களுக்கு நெருங்கிய உறவினனாய் எங்கும் காக்கிறான்.",
        '0.7': "மணிகளுக்குள் உள்ள நூல் போல பிரணவத்தால் உணர்த்தப்படுபவன் எல்லா சேதனக் கூட்டங்களிலும் இருந்து தன்னவர்களை இடைவிடாமல் காக்கிறான்; வணங்குவோரின் விருப்பம் அளிப்பவன், பக்தர்களின் சிந்தாமணி, சித்-ஆனந்தமே உடலாக உடையவன்; அணுவிலும் பெரியதிலும் இருந்து சிறியவன் போல உறைகிறான்.",
        '0.8': "சுஷும்னை முதலிய எல்லா நாடிகளின் கோசம் நாபி மூலத்தில், விருஷண ஆசனத்தின் நடுவில் 'துந்தி' என்ற பெயரில் உள்ளது. பிரம்மா முதலியோர் மூலேசனின் ஆனந்தம் முதலிய நற்குணங்களை உபாசித்தபடி உடல்களுக்குள் இருக்கிறார்கள்.",
        '0.9': "அறிஞர்கள் கவனிக்க வேண்டும்: பாகீரதி முதலிய தீர்த்தங்கள் எழுபத்தீராயிரம் நாடிகளில் உள்ளன. இந்த இரகசியத்தை அற்பர்களுக்குக் காட்டிச் சொல்லாமல் உறுதியுள்ளவர்கள் தினமும் நாடி நதிகளில் நீராடி மகிழ்கிறார்கள்.",
        '0.10': "இவ்வுடலின் இட-வல நாடிகளில் தேவர்கள் உள்ளனர் என்று அறி: பிரம்மா, வாயு, வாணி முதலியோர் வலப்புறம்; சேஷன், கருடன், சிவன், ஆறு மகிஷிகள், வாருணி, இந்திரன், காமன் முதலியோர் இடப்புறம் உள்ளனர்.",
        '0.11': "இரு பக்க நாடிகளிலும் தேவர்களுடன் விளையாடியபடி, கருடவாகனன் உயிர்களின் தகுதிக்கேற்ற சாதனையைச் செய்து செய்வித்து பக்தர்களை அன்புடன் காக்கிறான்; அசுரர்களுக்கு வெற்றி கிடைக்க விடாமல் அவர்களின் நற்புண்ணியங்களைப் பறிக்கிறான்.",
        '0.12': "துந்தியிலிருந்து தலை வரை ஒரே நாடி பரவியுள்ளது; அதனுள் தாமரையில் பிறந்த பிரம்மா இருக்கிறார்; அதற்குப் பத்துக் கிளைகள்; பதினொரு புலன்கள் அங்கே இணைந்துள்ளன; சூரியன், சந்திரன், வருணன், அஸ்வினிகள் முதலியோர் அங்கே எப்போதும் நிலைத்துள்ளனர்.",
        '0.13': "தொப்புளிலிருந்து ஒரே நாடி வளையாமல் நேராக நடு உடலில் 'சுஷும்னை' என்ற பெயரில் உள்ளது. அரக்கர்களை உள்ளே புக விடாமல், வாயுதேவன் பத்துத் திசைகளிலும் வேறு எவரையும் பொருட்படுத்தாமல் உடலில் சஞ்சரிக்கிறான்.",
        '0.14': "இத்தனை நாடிக் கிளைகள் இவ்வுடலில் உள்ளன; ஒரே ஆத்மாவான நாராயணன் எழுபத்தீராயிரம் வடிவினனாகி நாடிகளில் தன் துணைவியுடன் இரவும் பகலும் இவ்வாறு பிரம்மாண்டத்தின் எல்லா உயிர்களிலும் இருந்து மயக்குகிறான்.",
        '0.15': "நாளுக்கு நாள் வளரும் சந்திரனின் கதிர்களின் அழகைக் குருடன் கண்டு மகிழ முடியுமா? கீழ்மகனுக்கு இந்த நற்கதை அமுத விருந்தின் இன்பம் கிடைக்குமா? லக்ஷ்மியின் மனங்கவர்ந்தவனின் நற்குணங்களைப் பாடும் பக்தனுக்கே அன்றி வேறொருவனுக்குக் கிடைக்காது.",
        '0.16': "இவ்வுடலில் நாடிகள் நெசவின் பாவும் ஊடும் போலப் பின்னியுள்ளன; இந்திரன் முதலியோர் தம்மினும் உயர்ந்தோருடன் அங்கிருந்து, அசுரர்களை அச்சுறுத்தி, 'சந்தாதா' என்ற பெயருடைய ஹரியின் குணங்களில் அன்புடன் நல்லுபாசனை செய்து மகிழ்கிறார்கள்.",
        '0.17': "நீர்வாழ்வன, கோழி, பறவை முதலிய உயிர்களின் உடல்களில் இருந்து தன்னைக் காட்டாமல், அந்தந்த உருவ-பெயர்களால் அழைக்கப்பட்டு, தாமரைக்கண்ணன் பலவகைச் செயல்களை இடைவிடாமல் செய்து செய்வித்து, அவற்றின் பலன்களை உண்ணாமல் நித்திய சுகம் நிறைந்தவனாய்ச் சஞ்சரிக்கிறான். (இப்பாடலின் பாடம் முழுமையாகச் சரிபார்க்கப்படவில்லை.)",
        '0.18': "இவ்வாறு அறிந்து உபாசனை செய்தபடி, அழுக்கானவன் போல இருந்து தீயவர்களின் கண்ணில் படாமல், அறிஞர்களிடம் கர்வம் கொள்ளாமல், மழை, வெயில், பசி, தாகம், வெற்றி-தோல்வி, தீயோரின் இகழ்ச்சி-புகழ்ச்சி, அச்சங்களுக்கு அஞ்சாமல் மதயானை போலப் பூமியில் சஞ்சரி.",
        '0.19': "காட்டிலும் ஊரிலும் உள்ள எல்லா உயிர்களும் தினமும் செய்யும் எச்செயலும் ஹரி பூஜையே என்று அறிந்து, நற்பக்தியுடன் தியானித்து, வாயு முதலிய தேவர்களின் அந்தராத்மாவான ஸ்ரீநிவாசனுக்கு அர்ப்பணித்து மகிழ்ந்து களித்திரு.",
        '0.20': "காண்பதற்கு இனியவன் உலகில் நாய், பன்றி முதலியவற்றிலும் உறைகிறான்; இரண்டற்ற ஒருவனான அவன் பல உருவ-பெயர்களால் அழைக்கப்பட்டு உள்ளிருந்தும் தெரிவிப்பதில்லை; ஸ்ரீ, பிரம்மா முதலிய எல்லா தேவகணங்களாலும் ஆராதிக்கப்பட்டு ஏற்றுக்கொண்டு தினமும் காக்கிறான்.",
        '0.21': "இவ்வாறு உபாசிக்கும் நல்லோர் உலக வாழ்வில் தினந்தோறும் எதைச் செய்தாலும் அது எல்லாம் ஹரி பூஜை எனப்படும்; இது உண்மை. இச்சொல்லில் ஐயம் கொள்ளும் மனிதன் அற்பனே; அவன் புறச் சடங்குகளைச் செய்து பயன் என்ன? (இப்பாடலின் பாடம் முழுமையாகச் சரிபார்க்கப்படவில்லை.)",
        '0.22': "அனுபவிக்கப்படுவனவற்றிலும் அனுபவிப்பவர்களிலும் ஹரி தானே அனுபவப் பொருளும் அனுபவிப்பவனும் எனப்பட்டு, தக்க-தகாத சுவைகளைத் தேவ-அசுர கூட்டங்களுக்கு ஊட்டுகிறான். பாக்கிய நிதியான அவன் பக்தர்களுக்கு நல்ல வைராக்கியம், பக்தி, ஞானம் அளிக்கிறான்; தகுதியற்றவர்களுக்குத் தன்னிடம் வெறுப்பு முதலியவற்றை அளிக்கிறான்.",
        '0.23': "இப்பதினான்கு உலகங்களில் சராசர உயிர்களில் நாளும் உறைந்து, விரோசனன் மகனை (பலியை) ஏமாற்றியவன் 'யாசகன்' எனப்படுகிறான்; மாரீசனை அடக்கியவன் அழகிய ஹம்ஸ வடிவில் 'நிஷேசகன்' என்ற பெயருடன் மக்களின் விருப்பங்களை நிறைவேற்றுகிறான்.",
        '0.24': "அன்னம் அளிப்பவன், அன்னம் உண்பவன், அன்னமயன், தானே அன்னம்; பிரம்மா முதலிய எல்லா உயிர்களுக்கும் அநிருத்தன் முதலிய வடிவங்களால் உணவை அமைக்கிறான்; பிறரை எதிர்பாராமல் குண-கருணைக் கடலான அவன் படைக்கிறான்; ஹிரண்யகர்ப்பனுக்குள் இருந்து மூவுலகையும் காக்கிறான்.",
        '0.25': "மூன்றடியான், தேவர்களின் தலைவன், மூன்று இடங்களில் உறைபவன், மூவழி நதியின் (கங்கையின்) தந்தை, த்ரிவிக்ரமன், எளியோரிடம் அன்புடையவன், நீலத்தாமரை இதழ் போலக் கரியவன், எல்லையற்றவன், அளவற்ற சித்-சுக-குணங்களே உடலாக உடையவன், வைகுண்டம் முதலிய உலகங்களின் அதிபதி, மூவேத வடிவினன் தன்னவர்களைக் கபடமின்றிக் காக்கிறான்.",
        '0.26': "உப்பு கலந்த நீர் நாவுக்கு உப்பாகவே தோன்றும்; பார்ப்பவர்களால் அதைப் பிரித்துக் காட்ட முடியுமா? அவ்வாறே தன்வயத்தனும் எங்கும் பரவியவனுமான லக்ஷ்மீநாதன் சராசரங்களில் நிறைந்திருக்கிறான்; அறியப்படாத அவனை முழுமையாக அறிந்தவர் தேவர்களில் யார்?",
        '0.27': "சின்மயனான அவன் வியாபிக்கப்படுவது போல எல்லா உயிர்களுக்குள்ளும் இருக்கிறான்; கொடிய சம்சாரத்தால் வெந்தவர்கள் பக்தியுடன் வழிபட்டால் இம்மையிலும் மறுமையிலும் அடையத்தக்கவனாகிறான்; பக்தவத்சலன் அவர்களின் குறைகளைப் பொறுத்து, பிறப்பு முதலிய குற்றங்களை அவர்களுக்கு எப்போதும் விலக்குகிறான்.",
        '0.28': "பலவகையில் ஹரியை மகிழ்வித்து மனத்தில் நிறுத்தி, எந்த வேலை செய்தாலும் அது அவன் திருவடி பூஜை என்று நினைத்தபடி இரு; கலப்பையேந்தியின் தம்பியான கிருஷ்ணன் தானே எல்லா இடங்களிலும் உறைந்து அசையாத பக்தி, நல்லறிவு, நற்பேறு அளித்துக் காக்கிறான்.",
        '0.29': "குற்றத்தின் வாசனையும் அற்றவன், பலவேடம் பூண்பவன், மூவுலகையும் பேணுபவன், பழமையான புருஷன், இந்திரன் முதலியோரால் துதிக்கப்படுபவன், சேஷசயனன், விபீஷணனுக்குப் பிரியன், விஜயனின் (அர்ஜுனனின்) தோழன் தன்னை மகிழ்விக்கும் மக்களுக்கு விரும்பியவற்றை நிறைவேற்றுகிறான்.",
        '0.30': "'ஸ்ரீயும் பூமியும் சேவிக்கும் திருவடித் தாமரை உடையவனே, எல்லையற்றவனே, நற்பக்தியால் மட்டுமே அடையத்தக்கவனே, பிரம்மா முதலிய தேவர்களும் அசுரர்களும் அர்ச்சிக்கும் திருவடிகளை உடையவனே, அழகனே, வாமனா, ராமா, பிறவி நோய்க்கு மருந்தே, என் குலதெய்வமே, காத்தருள்!' என்று அழைத்தால் கருணையுள்ளவன் வந்து உதவுகிறான்.",
        '0.31': "அசுரர்களிலும் தேவர்களிலும் இருந்து அவரவருக்கேற்பச் செயல்களைச் செய்கிறான்; பிறப்பு-இறப்பு முதலிய எல்லாக் குற்றங்களுக்கும் அப்பாற்பட்ட அவன் நம்முடன் பிறக்கிறான், வாழ்கிறான், செல்வத்தைக் காக்கும் பாம்பு போல எக்காலமும் காக்கிறான்; காரணம் வேண்டாத உறவினன் அவன்.",
        '0.32': "சூரியன் வானில் உதிக்கும்போது மரங்களின் நிழல்கள் பூமியில் பரவுகின்றன; மறையும்போது அங்கேயே ஒடுங்குகின்றன. அவ்வாறே இம்மூவுலகும் வாயு முதலிய முதன்மைத் தேவர்களின் அந்தராத்மாவின் வசத்தில் உள்ளன; அவன் அவற்றைத் தன் வயிற்றில் வைத்துக்கொண்டு எல்லாச் செயல்களையும் பார்ப்பவர்களுக்குக் காட்டுகிறான்.",
        '0.33': "மூவுலகுக்கும் ஒரே ஆராதனைக்குரியவன், லக்ஷ்மியின் அழகிய தோள்களால் தழுவப்பட்டவன், தானே தோன்றியவன், சுகாத்மா, பொன்னிறத்தான், கருடவாகனன், அபயம் அளிப்பவன், எண்ணற்ற சூரிய-சந்திரர் போல ஒளிர்பவன், களங்கமற்றவன் தன்னை நாளும் வணங்குவோருக்கு எல்லா நன்மைகளையும் தாமதமின்றி அளிக்கிறான்.",
        '0.34': "அறிஞர்களிடமிருந்து அறி: காலை, நண்பகல், மாலை ஸவனங்கள் வசுக்கள், ருத்திரர், ஆதித்யர்களுக்கு உரியவை; அவர்களில் ஒளிரும் வாயுவுக்குள் க்ருதி, ஜயா, மாயா ஆகியோரின் நாயகனின் (ப்ரத்யும்னன், ஸங்கர்ஷணன், வாஸுதேவன்) மூன்று மூர்த்திகளைச் சிந்தித்து, நாள்கள் என்ற ஆஹுதிகளால் அர்ச்சித்து மகிழ்ந்திரு.",
        '0.35': "இருபத்துநான்கு ஆண்டுகள் வசு தேவர்களில் ப்ரத்யும்னன் இருக்கிறான்; நாற்பத்துநான்கு ஆண்டுகள் ஸங்கர்ஷணன் எனப்படுபவன் நெருப்புக்கண்ணனான ருத்திரனில் இருக்கிறான்; நாற்பத்தெட்டு ஆண்டுகள் வெண்ணிற உடலுடைய மாயாபதி (வாஸுதேவன்) ஆதித்யனில் இருக்கிறான்.",
        '0.36': "நூற்றுப்பதினாறு ஆண்டுகளில் நூற்றுப்பதினாறு அழகிய வடிவங்களால் வசு, ருத்திர, ஆதித்யர்களில் துணைவியுடன் விளையாடுகிறான்; நாணமின்றி வழிபடும் பக்தர்களை வருத்தும் பாவ வெள்ளங்களை வெகுதூரம் ஓட்டி, பயம் போக்குபவன் விடாமல் அருகிலேயே உறைகிறான்.",
        '0.37': "83,520 வடிவங்களால் பகல்-இரவுகளின் அதிபதிகளில் நாளும் தோன்றுகிறான்; பாரதி-பிராணனுக்குள் இருந்து பக்தர்களின் பாவங்களை விலக்கி, ஹிங்காரம், நிதனம் முதலிய வடிவங்களால் பித்ருக்களைக் காக்கிறான்.",
        '0.38': "மிகச் சிறந்த தூய கம்பளி ஆடையை வேண்டுமென்றே சேற்றில் தோய்த்து எடுத்தால், சோதித்துப் பார்க்கையில் சேறு ஒட்டுமா? பத்மநாபன் எல்லா உயிர்களிலும் இருந்தாலும் முக்குணங்களால் கட்டுண்பானா? அவன் நித்திய சுகாத்மா, சின்மயன்.",
        '0.39': "எல்லாக் குற்றங்களுக்கும் அப்பாற்பட்டவன், ஆயிரக்கணக்கான சந்திரர், அக்னிகள், எண்ணற்ற சூரியர் கூட்டம் போல ஒளிரும் உடலுடையவன், லக்ஷ்மியின் கணவன், தேவர்களின் நண்பன்; பிரம்மாண்டத்திலுள்ள பிரம்மா முதலிய எல்லா சேதனக் கூட்டத்துக்கும் தானே தோழன் எனப்பட்டு, வஞ்சகமற்றவனாய் அவர்களைப் போலவே இருக்கிறான்.",
        '0.40': "வெவ்வேறு இடங்களில் உள்ள ஆகாயம் போல அவன் உயிர்த் தொகுதியில் எந்த இடைவெளியும் இன்றி எப்போதும் உறைகிறான்; ஸ்ரீயுடன் எங்கும் ஆகாயம் இடம் தருவது போலத் தந்து, எதையும் எதிர்பாராமல் அனைவரின் அந்தராத்மா சுகம் அளிப்பவனாய் ஒளிர்கிறான்.",
        '0.41': "ஸ்ரீ, பிரம்மா முதலிய தேவகணங்கள் சேவிக்கும் திருவடித் தாமரை உடையவன் இந்த ஜட-ஜீவ தொகுதிகளின் உள்ளும் புறமும் எப்போதும் உறைந்து, 'இடமுடையவன்' எனப்பட்டு, தன் உடலிலேயே அவற்றை வைத்துக்கொண்டு பேணுகிறான்; அவன் தேவன், தேவகியை மகிழ்விப்பவன், அசுரரை அழிப்பவன், மரணத்தை வென்றவன்.",
        '0.42': "ஒரு மாதத்துக்கு, தினசரிக் கணக்குப்படி, மூச்சுகள் 6,48,000 ஆகின்றன; ஹம்ஸன் என்ற பெயருடைய ஹரியை நூற்றுப்பதினாறு ஆண்டுகள் இவற்றால் வழிபட்டால் கருணைக்கடல் குசேலனிடம் மகிழ்ந்தது போல நாள்தோறும் மகிழ்கிறான்.",
        '0.43': "ஸ்தூல உடலில் இருந்து வாயுதேவன் கருணையால் ஓர் ஆண்டுக்கு 77,76,000 மூச்சு ஜபங்களைப் பதினான்கு உலகங்களிலுள்ள உயிர்த் தொகுதியில் செய்கிறான்; அவன் மூவுலகிலும் பரவியவன், மிக நெருங்கியவன்.",
        '0.44': "நான்கு உடல்களில் இருந்து வாயுதேவன் மூவகை உயிர்களுக்குள் நாளொன்றுக்கு 86,400 மூச்சு ஜபங்களைச் செய்கிறான்; பவனராயன் மீது கரனின் பகைவனின் (ராமனின்) கருணை வலிமை எத்தகையதோ!",
        '0.45': "ஸ்ரீயின் நாயகனான ஜகந்நாத விட்டலன் கருணையுடன் என் வாயில் பேசியபடியே நான் பேசினேன், வேறல்ல; அறிஞர்களே, கேளுங்கள். சாதுக்களின் அடையாளத்தை மட்டும் காட்டுபவர்கள் இதை மறுத்தால் என்ன? இதில் என் குற்றம் என்ன என்பதை அறிஞர்கள் ஆராய்ந்து சொல்லட்டும்.",
      },
    },
    'harikathamrutasara-13': {
      summary: "பதின்மூன்றாம் ஸந்தி (நாமஸ்மரணம்): விளையாட்டு, கொட்டாவி, நீராடல் என எல்லா நிலைகளிலும் ஹரியை நினைப்பவன் பாவங்களிலிருந்தும் யமதூதர்களிடமிருந்தும் தப்புகிறான். எல்லாச் செயல்களுக்கும் கர்த்தா ஹரியே என்று அறிந்து செயல்களை அவனுக்கு அர்ப்பணிக்க வேண்டும்; தேவர்கள், ஞானிகள் ஆகியோரின் பூஜை அவனது பிரதிமைகள் வழியாக அவனுக்கே செய்யும் பூஜை. அவன் பஞ்சபூதங்கள், மழை, காடு, நீர் ஆகியவற்றில் நிலைத்து ஒவ்வொரு ஜீவனுக்கும் தகுந்த ரஸங்களை ஊட்டுகிறான்; இந்த ரஹஸ்யத்தை உண்மையான பக்தர்களுக்கு மட்டுமே சொல்ல வேண்டும்.",
      verses: {
        '0.0': "குருவின் கருணையால் ஹரிகதாம்ருதஸாரத்தைச் சொல்கிறேன்; பரம பகவத்பக்தர்கள் இதை ஆதரவுடன் கேட்க வேண்டும்.",
        '0.1': "குழந்தைகளுடன் விளையாடும்போதும், மனைவியுடன் அன்புடன் மகிழும்போதும், குதிரை, பல்லக்கு, யானை முதலான வாகனங்களில் ஏறி உலா வரும்போதும், விக்கும்போதும், கொட்டாவி விடும்போதும் தேவகியின் மகனான கிருஷ்ணனை நினைக்கும் மனிதன் எங்கு பார்த்தாலும் யமதூதர்களிடம் சிக்குவதில்லை.",
        '0.2': "அழகிய ஆடை அணிந்திருக்கும்போதும், கடிதம் முதலியவற்றில் ஈடுபட்டிருக்கும்போதும், மகிழ்ச்சி, கோபம், மறதி ஆகியவற்றாலும் எப்படியாவது ஒருமுறை வாய்திறந்து 'ஹரி' என்ற இரண்டு எழுத்துகளைச் சொன்னாலே, பஞ்சுக்குவியலில் நெருப்பு விழுந்ததுபோல் பாவங்கள் எரிந்துவிடும்.",
        '0.3': "படுக்கும்போதும், எழும்போதும், அமர்ந்து பேசும்போதும், வீட்டில் வேலை செய்யும்போதும், நீராடும்போதும், உண்ணும்போதும், எல்லா இடங்களிலும் அந்த ஹரியின் நாமரூபங்களை நினைப்பவர்களின் அருகில் குற்றமற்ற அவன் அரை நொடியும் அவர்களை விட்டு அகலாமல் இருக்கிறான்.",
        '0.4': "எந்தக் குலத்தவனாக இருந்தாலும், எந்த நாட்டில் இருந்தாலும், எந்தச் செயலைச் செய்தாலும், எந்தக் காலத்திலும், ஸ்ரீவரனான ஹரியை எங்கும் தியானித்து பூஜித்து மகிழும் ஞானிகளுக்கு பயம், துன்பம் போன்ற குற்றங்கள் ஏது?",
        '0.5': "வாசுதேவனின் குணக்கடலில் நீந்தத் தெரிந்தவன் உலகில் சிரமமின்றி சம்சாரக்கடலை விரைவில் கடக்கிறான். சலிப்பின்றி தீய விஷயங்களின் ஆசையில் உழல்பவன், பக்தி என்னும் நல்வழியைக் காணாமல் பல துன்பங்களை அனுபவிக்கிறான்.",
        '0.6': "நீராடல், ஜபம், தேவபூஜை, உபன்யாசம், மஹாபாரதம் முதலிய பெரிய உபபுராணக் கதைகளை நாள்தோறும் சொல்லிக் கேட்டாலும் என்ன பயன், ஞானேந்திரியங்களாலும் கர்மேந்திரியங்களாலும் செய்யும் செயல்களையெல்லாம் லக்ஷ்மீநிவாசனின் பூஜையாக அர்ப்பணிக்காத மனிதனுக்கு? (வாக்கியம் அடுத்த பாடலில் முடிகிறது.)",
        '0.7': "தேவகங்கையில் இருப்பவனுக்குப் பாவக்குவியல் உண்டோ? கருடனின் இல்லத்தில் இருக்கும் பாம்புகளுக்கு அச்சம் உண்டோ? அவ்வாறே ஜீவனின் கர்த்ருத்வத்தை மறந்து, உயர்ந்தோர் தாழ்ந்தோர் அனைவருக்கும் ஈசனான ஹரியே கர்த்தா என்று அறிந்தவன் எந்தச் செயலைச் செய்தாலும் அச்செயல்கள் அவனைப் பற்றாது.",
        '0.8': "'புண்ணிய பாவங்களை நானே செய்கிறேன்' என்பவன் அதமன்; அவன் தீய கர்மத்துக்கு உரியவனாகிறான். புண்ணியத்துக்கு ஹரியே கர்த்தா என்னும் மனிதன் மத்யமன். இரண்டு வகைச் செயல்களுக்கும் ஸ்ரீநிவாஸனே கர்த்தா என்று எப்போதும் அன்புடன் நினைத்து மகிழ்பவர்களே மனிதரில் உத்தமர்கள்.",
        '0.9': "உலகில் உபாசனைக்கு உரியவர்கள் தேவர்களே, வெறும் மனிதர்கள் அல்ல. எவ்வகையில் செய்தாலும் இவர்களின் அர்ச்சனை ஹரி பூஜையே; ஏனெனில் இவர்கள் ரமாவிநோதனான ஹரியின் பிரதிமைகள் எனப்படுகிறார்கள். முக்திக்குத் தகுதியானவர்களுக்கு இவர்களின் அனுக்ரஹமே ஹரியின் வரானுக்ரஹமாகக் கருதப்படுகிறது.",
        '0.10': "'உடலே நான்', 'மனைவி, பிள்ளைகள், வீடு, செல்வம் ஆகியவை என்னுடையவை' என்பவனையும், கங்கை முதலிய நீர்களே உண்மையான தீர்த்தம் என்பவனையும், அக்னி, உலோகம் முதலிய சின்னங்களின் அர்ச்சனையே இறைவனின் பூஜை என்பவனையும், நல்லோர் வெறும் மனிதர்களே என்பவனையும் ஞானிகள் 'கோகரன்' (பசு-கழுதை போன்ற மூடன்) என்கின்றனர்.",
        '0.11': "அக்னி, சந்திரன், சூரியன், நட்சத்திரங்கள், பூமி, கங்கை முதலிய முக்கிய தீர்த்தங்கள், வாயு, ஆகாயம், மனம் முதலிய இந்திரியங்களுக்கு அபிமானிகளான தேவர்கள், ஞானிகளைப்போல் நல்ல மனத்துடன் வழிபடாதவர்களைப் புனிதப்படுத்துவதில்லை; அவ்வாறிருக்க அவர்களின் பூஜையை மட்டும் செய்தால் போதுமா?",
        '0.12': "நெருப்புத்துண்டைப் பார்க்காமல் தொட்டாலும் சரி, பார்த்துத் தொட்டாலும் சரி, அது சுடாமல் இருக்குமா? அதுபோல் தாமரைக்கண்ணனான ஹரியின் தூய திருவடித்தாமரையின் வண்டுகளான பக்தர் கூட்டம், பார்த்த மாத்திரத்தில், தங்கள் முன் விழுந்து வணங்கியவனை அந்தக் கணமே புனிதப்படுத்துகிறது.",
        '0.13': "ஆகையால் மீண்டும் மீண்டும் ஞானிகளுடன் பழகு; தீயவர்களுடன் கலக்காதே. உலக வாழ்வில் மயங்காமல், கருடனின் தோளில் ஏறிய ஹரியின் நாமரூபங்களை எல்லா இடங்களிலும் தியானித்தபடி சஞ்சரி; பிற எண்ணங்களை விட்டுவிடு.",
        '0.14': "தாமரையில் பிறந்தவனின் இந்த அண்டத்தில் ஹரி எல்லா உயிர்களிலும் இடைவிடாது நிலைத்து, அவர்களுக்குத் தெரியாமலேயே அவர்களின் அறிவுசார் செயல்களை நடத்துகிறான். எதையும் காணாமல் 'எல்லாச் செயல்களையும் நானே செய்கிறேன்' என்பவன் தீய பிறவியை அடைகிறான்; 'கர்த்தா ஹரியே' என்று அறிந்தவனே முக்தனாகிறான்.",
        '0.15': "கலியின் மாசை நீக்கும் கங்கையில் சஞ்சரித்து வாழும் நீர்வாழ் உயிர்கள் அந்தத் தீர்த்தத்தின் மகிமையை அறிவார்களா? அதுபோல் ஹரியின் கருணையால் பல வகையிலும் வலிமை பெற்ற பிரம்மா, வாயு, சிவன் முதலிய தேவர்களும் அனந்தனின் தூய குணங்களை அறியமாட்டார்கள்.",
        '0.16': "ஸ்ரீலக்ஷ்மீவல்லபன் இதயத்தாமரையில் இருந்து எல்லா உயிர்களையும் மயக்கி, முக்குணங்களால் கட்டி, பருவுலகச் செயல்களில் ஈடுபடுத்தி, தன் அழகிய லீலைகளைத் தெரிவிக்காமல் குயவனின் சக்கரம்போல் மனிதர்களை சம்சாரத்தில் சுழற்றுகிறான்.",
        '0.17': "வேதசாஸ்திரங்களை ஆராய்ந்து, விலக்கப்பட்ட செயல்களை விட்டு, தினமும் நற்செயல்களைச் செய்பவர்களுக்கு அவன் சொர்க்கம் முதலிய சுகத்தை அளிக்கிறான்; பாவிகளை நரகத்தில் சேர்க்கிறான்; மனிதர்களுக்குத் துன்ப இன்பங்களைத் தருகிறான்; தீய வாதம் செய்வோருக்கு அந்தந்தமஸ்ஸில் பெருந்துன்பங்களை உண்ணச் செய்கிறான்.",
        '0.18': "நிர்குணனாக உபாசிப்பவனுக்கு குணங்களின் சேர்க்கையால் வரும் குற்றங்களைத் தராமல், கருணைக்கடலான ஹரி மோக்ஷத்தில் சுகம் அளித்துக் காக்கிறான். தன்னை அடைவது அரிது என்று கருதும் த்ரைவித்யர்களுக்கு, முக்குணங்களைக் கடந்தவனான அவன் சொர்க்கம், பூமி, நரகம் ஆகியவற்றில் இடைவிடாத சஞ்சாரத்தை ஏற்படுத்துகிறான்.",
        '0.19': "மூவரின் (மூன்று வகை ஜீவர்களின்) உள்ளே இருந்தாலும் அவனுக்குச் சுகதுக்கங்களின் தொடர்பு ஏற்படாது; புனிதர்களுக்கும் புனிதன், பரத்தினும் பரன், முழுமையான இன்பக்கடல் ஆன பராவரேசன் இந்த அண்டத்தில் தன் உடலையே அந்த வடிவாக்கிக் கொண்டு அசையும், அசையாத உலகங்களைக் காக்கிறான்.",
        '0.20': "தன்னிச்சையான கர்த்ருத்வ எண்ணத்தை மறந்து, 'செய்யப்படுவதெல்லாம் ஹரி உள்ளும் புறமும் நிலைத்து தானே செய்கிறான்' என்று அறிந்து, மதயானைபோல் அச்சமின்றி சஞ்சரி. வாயுவால் வணங்கப்படும் அவன் அரை நொடியும் உன்னை விட்டு அகலமாட்டான்.",
        '0.21': "பல கர்மங்களைச் செய்து உடலை வருத்தாமல், நாள்தோறும் இதயமாகிய தூய இல்லத்தில் விளங்கும் ஹரி மூர்த்தியையே வழிபடு. இந்தப் பூஜை முறையை அறியாமல் பழம், பூ, நீர், துளசி இலை ஆகியவற்றை மட்டும் அர்ப்பணித்தால் வாசுதேவன் ஏற்பதில்லை.",
        '0.22': "பூமியில் நாராயணன், நீரில் துரீயன் என்ற பெயருடையவன், நெருப்பில் ஸங்கர்ஷணன், காற்றில் ப்ரத்யும்னன், ஆகாயத்தில் அநிருத்தன் இருக்கிறார்கள். இவ்வாறு ஐந்து வடிவங்களை ஏற்று, பூதங்களைத் தன் நாமரூபங்களால் அழைக்கச் செய்து மக்களைத் தேற்றுகிறான்.",
        '0.23': "நாராயணன் தானே மேகத்தில் இருந்து தன் பெயரால் அழைக்கப்படுகிறான்; மேகத்தின் கருவில் உள்ள நீரில் வாசுதேவன் என்ற பெயரில் நிலைத்திருக்கிறான்; இடி முழக்கத்தில் ஸங்கர்ஷணன், மின்னலில் ப்ரத்யும்னன், மழைத்துளிகளில் அநிருத்தன் இருக்கிறார்கள்; இவ்வாறு அவனே மழை எனப்படுகிறான்.",
        '0.24': "வீடு, குடும்பம், செல்வம் முதலியவற்றின் பிணைப்புடையவர்களாய், விதிக்கப்பட்டவை, விலக்கப்பட்டவை ஆகிய தர்மங்களையும் நற்செயல்களையும் அறியாமல், நாளும் உணவு, இன்பம், உறக்கம் ஆகியவற்றில் ஆழ்ந்த எல்லா உயிர்களும் இதயக்குகையில் வாழும் ஹரியை அறியாமல் சம்சாரத்தில் தவிக்கின்றன.",
        '0.25': "பிரம்மா, கருடன், சேஷன், ருத்ரன் ஆகியோருடன் கூடி விளங்கி, அவன் காட்டிலும் எப்போதும் இருக்கிறான். சந்திரன் வழியாக வளர்ச்சியை அளித்து, பறவைகள், விலங்குகள், பாம்புகளின் உடல்களை அந்தந்தப் பெயர் கொண்ட வடிவில் காக்கிறான்.",
        '0.26': "அளவற்ற மகிமையுடைய நரஹரி காட்டில் காக்கிறான்; பூமியை அளந்த கேசவன் எல்லா இடங்களிலும்; கபதி வானத்தில்; மகாமத்ஸ்யன் என்ற பெயருடையவன் நீரில்; கருணையுள்ள அவன் நாள்தோறும் பக்தர்களை வஞ்சனையின்றிக் காக்கிறான்.",
        '0.27': "(இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.) காரணங்களின் அந்தர்யாமியான ஹரி, அவனது பருவடிவ அவதாரங்கள், அவனுக்கு அர்ப்பணிக்கும் ஆறு சுவைகள் ஆகியவை இதில் குறிப்பிடப்படுகின்றன. தெளிவான உபதேசம்: இந்த ரஹஸ்யத்தை வெளிப்படுத்தாமல், எல்லையற்ற மகிமையுடையவனின் ரூபகுணங்களை எப்போதும் நினைத்து இன்புற்றிரு.",
        '0.28': "'பிரதிபிம்பத்தை உண்போம்' என்ற மகிழ்ச்சியுடன் நீர்வாழ் உயிர்கள் நாளும் முயல்வதுபோல், மக்கள் பலராமனின் தம்பியான கிருஷ்ணனே எல்லா இன்பச்சுவைகளின் உண்மையான உறைவிடம் (பிம்பம்) என்பதை அறியாமல் பிறரை வழிபட்டு புருஷார்த்தங்களுக்காக ஏங்குகிறார்கள்.",
        '0.29': "தேவர்கள், ரிஷிகள், கந்தர்வர்கள், பித்ருக்கள், மனிதர்கள், அரசர்கள், அசுரர்கள், பசு, ஆடு, கழுதை, செம்மறி முதலிய எல்லா உயிர்களின் அனுபவிக்கும் சுவைகளை ரமாபதி அவர்களின் உறுப்புகளுக்குள் இருந்து ஏற்கிறான்; ஒவ்வொரு ஜீவகணத்துக்கும் அதன் தகுதிக்கேற்ற சுவைகளை எப்போதும் ஊட்டுகிறான்.",
        '0.30': "கடின புத்தியை விட்டு, உலகியல் வீண்பேச்சுகளைத் துறந்து, பொன், துணி, மண்கட்டி ஆகியவை சமம் என்று அறிந்து, அண்டத்தைத் தன் வயிற்றில் கொண்ட ஹரி எல்லோருக்குள்ளும் இருந்து அவர்களின் செயல்களைச் செய்கிறான் என்று அடிக்கடி நினைத்துக்கொண்டிரு.",
        '0.31': "உலகில் மக்கள் மர்மத்தைத் தொடும் சொற்களைக் கேட்டால் பொறுக்காமல் மிகுந்த கோபத்துடன் அடிக்கிறார்கள். ஆனால் 'மாமனைக் கொன்றவனே, ஜாரனே, வெண்ணெய்த் திருடனே' என்று அழைத்தாலும் கருணையுள்ள ஹரி அவ்வாறு அழைத்தவர்களைத் தன் இல்லத்தில் வைத்துத் தேற்றுகிறான்.",
        '0.32': "இந்த ஹரிகதாம்ருதஸாரத்தை ஸாதுக்கள் எப்போதும் கவனமுடன் கேட்க வேண்டும்; கடுமையானவர்களுக்கும், புறங்கூறுபவர்களுக்கும், தகுதியற்றவர்களுக்கும் இதைச் சொல்லக்கூடாது. நல்ல பக்தியுடன் இறைவனின் சரிதங்களைப் புகழ்ந்து மகிழும் பரம பாகவதர்களுக்கே இந்த ரஹஸ்யத்தைத் தெரிவிக்க வேண்டும்.",
        '0.33': "ஸத்யஸங்கல்பனான ஹரியே எப்போதும் துதிக்கத்தக்கவன், பரம புருஷார்த்தம் என்று அறிந்து, மிகுந்த மகிழ்ச்சியுடன் அவனை நினைத்தபடி போகங்களை அனுபவி. நித்திய சுகம் நிறைந்தவனும் பரம சுஹ்ருத்தமனுமான ஜகந்நாத விட்டலன் சம்சாரக்கடலை வற்றச்செய்து சித்சுகத்தின் வெளிப்பாட்டை அளிக்கிறான்.",
      },
    },
    'harikathamrutasara-14': {
      summary: "பதினான்காம் ஸந்தி (பித்ருகணவிசாரம்): ஹரி தொண்ணூற்றாறு நாமங்களாலும் ஆயிரக்கணக்கான வடிவங்களாலும் பித்ருகணங்களின் அபிமானிகளான வஸு-ருத்ர-ஆதித்ய தேவர்களிலும், நைவேத்ய அன்னத்திலும், ஒவ்வொரு உண்பவரிலும் உண்ணப்படும் பொருளிலும் நிலைத்து, பக்தர்களின் அர்ப்பணத்தை ஏற்று, பித்ருக்களுக்கு அளவற்ற சுகத்தை அளிக்கிறான். ஹரி-ஜீவன், ஹரி-ஜடம், ஜீவன்-ஜீவன், ஜீவன்-ஜடம், ஜடம்-ஜடம் என்ற பஞ்சபேதம், உலகம் ஹரியின் பிரதிபிம்பம் என்ற உறவு, இந்த ரஹஸ்யத்தை யாருக்குச் சொல்ல வேண்டும் என்ற கவனம் ஆகியவற்றையும் இந்த ஸந்தி கூறுகிறது.",
      verses: {
        '0.0': "குருவின் கருணையால் ஹரிகதாம்ருதஸாரத்தைச் சொல்கிறேன்; பரம பகவத்பக்தர்கள் இதை ஆதரவுடன் கேட்க வேண்டும்.",
        '0.1': "(இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.) க்ருதிரமணனும் ஜயாபதியுமான ஹரி ப்ரத்யும்னன், வாசுதேவன் முதலிய வடிவங்களில் மூவகை அஹங்காரத்தின் உள்ளே இருந்து இருபத்துநான்கு வடிவங்களால் போக்யன் எனப்படுகிறான்; நெருப்பு, இந்திரியங்களுக்குள்ளும் போக்தாக்களுக்குள்ளும் இருந்து முப்பத்துமூன்று வடிவங்களால் போக்தா எனப்படுகிறான்.",
        '0.2': "(இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.) முப்பதுக்கு மேற்பட்ட வடிவங்களில் அவன் சூரியனில் இருக்கிறான். மாயாரமணனான ஸ்ரீவாசுதேவன் மூவகை பித்ருக்களிடையே 'காலன்' என்ற பெயரில் இருக்கிறான்; வஸு, ருத்ர, ஆதித்யர்களுக்குள் இருக்கும் அநிருத்தன் தன்னை வெளிக்காட்டாமல் கர்த்தா, கர்மம், கிரியை என்று அழைக்கப்படுகிறான்.",
        '0.3': "சுதந்திரனான நாராயணன் தொண்ணூற்றாறு பெயர்களால் அழைக்கப்பட்டு, வஸு, ருத்ர, ஆதித்யர்களிலும் கர்த்தா, கர்மம், கிரியை ஆகியவற்றிலும் நிலைத்து, எந்தச் சாக்கும் இன்றி தன்னவர்கள் தினமும் செய்யும் சேவையை ஏற்று, அவர்களின் பித்ருக்களுக்கு அளவற்ற சுகங்களை அளிக்கிறான்.",
        '0.4': "துணியில் இழைகள்போல் லக்ஷ்மீகாந்தன் ஐந்து வடிவினனாகி கர்த்தாக்களான வஸு, ருத்ரன், சூரியன் ஆகியோருக்குள் எப்போதும் இருக்கிறான். தன்னைச் சிந்திக்கும் ஸாதுக்களை, குரு மத்வரின் அந்தராத்மாவான அவன் இம்மையிலும் மறுமையிலும் அனைத்து விருப்பங்களையும் அளித்துத் தேற்றுகிறான்.",
        '0.5': "தாய் தந்தையரின் மகிழ்ச்சிக்காக இழிவான செயல்களை விட்டு, விதிக்கப்பட்ட கடமைகளில் ஒன்றையும் மீறாமல் அங்கங்களுடன் கூடிய செயல்களைச் செய்பவர்கள் வணங்கத்தக்கவர்கள். அவர்கள் பூமியில் நாள்தோறும் தெய்வீக, உடல்சார் சுகங்களுடன் நீண்டகாலம் புகழுடன் வாழ்கிறார்கள்.",
        '0.6': "ஹம்ஸவாகனனான பிரம்மா முதலிய தேவர்கள் ஹரியின் மூன்று அம்சங்களைத் தாங்கியவர்கள் என்று அறிந்து, அந்தராத்மாவான ஜனார்த்தனனை நினைத்தபடி, அவனது மூன்று தொகுதி முப்பத்தாறு வடிவங்களை அறிந்து, கருடவாகனனை வழிபடுபவர்களே கிருதார்த்தர்கள் ஆவார்கள்.",
        '0.7': "மூவாயிரத்து ஐந்நூற்று ஐம்பத்தைந்து வடிவங்களில் கரனின் பகைவனான ஜனார்த்தனன், அறிஞர்கள் செய்யும் சமாராதனைக்கு இடையூறுகள் வராதபடி பல வகைகளில் காக்கிறான்; அவன் எல்லா உடல்களுக்குள்ளும் இருந்து அவரவர் பெயரால் அழைக்கப்படுகிறான்.",
        '0.8': "ஜய ஜய ஜயாகாந்தா, தத்தாத்ரேயா, கபிலா, மஹிதாஸா, பக்தப்ரியா, புராதன புருஷா, பூர்ணானந்தா, ஞானகனா, ஹயவதனா, ஹரி, ஹம்ஸா, மூவுலகினும் வேறுபட்டவனே, அனைத்து உலகின் ஆதாரமே, நோயற்றவனே, கருணையுடன் காத்தருள் என்று பிரார்த்திக்க வேண்டும்.",
        '0.9': "அக்ஷரனாலும் (லக்ஷ்மியாலும்) துதிக்கப்படும் ஹரி தொண்ணூற்றாறு பெயர்களால் அழைக்கப்பட்டு, தன்னவர்கள் நல்ல பக்தியுடன் செய்யும் புண்ணியச் செயலை ஏற்று, கருணைக்கடலாய், பிராம்மண்யதேவனாய், பவக்கடலைக் கடக்கும் படகாய் அவர்களைப் பல வகையில் காக்கிறான்.",
        '0.10': "(இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.) உடல்களைத் தருபவன் அவரவர் உணவைத் தராமல் இருப்பானா? நல்லோரால் போற்றப்படுபவன், மங்கலச் சரிதன், நற்குணம் நிறைந்தவன் ஆன அவன் இம்மை மறுமை இன்பங்களை அளிக்கிறான்; முதுகில் மலையைத் தாங்கி பிரம்மாதிகளுக்கு அமுதம் ஊட்டி அவர்களின் பகைவர்களை அழித்தான்.",
        '0.11': "பிரம்மா முதலிய தேவர்களுக்கு மாயாரமணன் தானே ஸ்வாஹா வடிவாகி எப்போதும் திருப்தியளிக்கிறான்; பித்ருக்களுக்கு உணவாகும் ஸ்வதா என்ற வடிவில் ஸங்கர்ஷணன் இருக்கிறான்; பூமியில் பிறக்கும் பழம், புல் ஆகிய பெயர்களில் ப்ரத்யும்னனும் அநிருத்தனும் இருக்கிறார்கள்.",
        '0.12': "அவனே மனிதர்களுக்கும் விலங்குகளுக்கும் உணவு எனப்படுகிறான். ஹிரண்யகர்ப்பனின் அண்டத்தில் இவ்வாறு தன்னை உபாசிக்கும் பக்தர்களைத் துன்புறுத்தாமல், பவக்கடலைக் கடக்கச்செய்து, நால்வகை உணவு வடிவான ஹரி ஆத்மதரிசன சுகத்தை அளிக்கிறான்.",
        '0.13': "மனம், மொழி, உடல் ஆகியவற்றால் தினமும் செய்யும் தகுந்த, தகாத செயல்களையும், 'இது அன்னம், வாயுதேவனுள் இருக்கும் நாராயணனுக்கு, கிருஷ்ணார்ப்பணம்' என்று நல்ல பக்தியுடன் அர்ப்பணித்தால், கருணையுள்ள அவன் ஏற்றுத் தேற்றுகிறான்.",
        '0.14': "ஏழு வகை உணவுகளின் விளக்கத்தை அறிஞர்களின் வாயால் கேட்டு, சோம்பலின்றி காலந்தோறும் அநிருத்தன் முதலிய வடிவங்களை நினைத்து வழிபடு; மந்தபுத்தியுடையவர்களுக்கு இதைச் சொல்லாதே. ஸ்ரீலக்ஷ்மீவல்லபனே அன்னமும் அன்னாதனும் (உண்பவனும்).",
        '0.15': "இதை அறிந்து ஏழு அன்னங்களையும் நாள்தோறும் மறவாமல், இது மஹாயஜ்ஞம் என்று அச்சமின்றி கோவிந்தனுக்கு அர்ப்பணி. இந்திரேசன் அதை ஏற்று, கருணையுடன், கேட்காமலேயே ஆர்வத்துடன் தன் தாசர்களுக்குப் பரம மங்கலத்தைக் கொண்டுவந்து தருகிறான்.",
        '0.16': "கையில் ஊசியைப் பிடித்துக்கொண்டு 'போரை வெல்வேன்' என்னும் மனிதனைப்போல், இவ்வுலகின் அறிவிலிகள் உலகநாதனின் திருவடித்தாமரைகளைப் பக்தி ஞானத்துடன் நாளும் பூஜிக்காமல் தர்மம், அர்த்தம், காமம் ஆகியவற்றை விரும்பித் துன்புறுகிறார்கள்.",
        '0.17': "சகடாசுரனை அழித்த ஹரி எல்லா உயிர்களுக்கும் அருகில் இருந்து, உலகுக்கு வெளிப்படாமல் எல்லாச் செயல்களையும் தானும் செய்து செய்யவும் வைக்கிறான்; வஞ்சனையற்ற அவன் எல்லாக் காலத்திலும் பக்தர்களுக்கு சுகம் அளிக்கிறான். ஐயோ, இவனது பெரும் மகிமைகளைப் பற்றி என்ன சொல்வேன்!",
        '0.18': "ஸ்ரீலக்ஷ்மீவல்லபன் வைகுண்டத்தில் இருந்து, ப்ரணவம், ப்ரக்ருதி, பிரம்மா முதலிய உயிர்களுக்குள் நிலைத்து, மூலகாரணனான அவன் அம்சப் பெயர்களால் லீலை செய்து, பாலில் நெய் இருப்பதுபோல் மூன்று இடங்களில் வெளிப்படாமல் இருக்கிறான்.",
        '0.19': "மூன்று யுகங்களில் மூலரூபனான ஹரி ஞானிகளைக் காக்கவும், திதியின் புதல்வர்களை அழிக்கவும், தர்மத்தை நிலைநாட்டவும் எண்ணி, கருணையுடன் தன் பரிவாரத்துடன் பூமியில் அவதரித்து, எல்லா உயிர்களுக்கும் மனிதரைப்போன்ற பல நடத்தைகளைக் காட்டினான்.",
        '0.20': "(கடைசி வரி தெளிவற்றது.) காரணம் எனப்படும் ப்ரக்ருதிக்குள் இருந்து இருபத்துநான்கு தத்துவங்களைப் படைத்து, அவற்றின் உருவம், பெயர்களைத் தாங்கி, அண்டத்தை உருவாக்கி, காரியம் எனப்படும் வடிவங்களில் நாள்தோறும் வெளிப்படுகிறான்.",
        '0.21': "ஜீவர்களின் அந்தர்யாமியான அம்சி உடல்களிலும் இந்திரியங்களிலும் நிலைத்து, அம்சப் பெயர்களால் தினமும் விஷயங்களை ஏற்று, தான் இன்பமயனாய் அவற்றை உண்டு, தேவர், மனிதர், அசுரர்களுக்கு இடைவிடாது சுகத்தையும் சம்சாரத் துன்பத்தையும் தருகிறான்; அவன் சுதாமனின் நண்பன்.",
        '0.22': "நாடுநாடாகச் சுற்றி உடலை வருத்தாமல், பலனை விரும்பும் செயல்களின் தீய ஆசைக்கு உட்படாமல், பிரம்மா முதல் எல்லா உயிர்களும் நிலம், நீர், நெருப்பு, காற்று, ஆகாயம் முதலிய எல்லாத் தத்துவங்களும் பரமாத்மனுக்கு அதிஷ்டானம் என்று அறிந்து இடைவிடாது வழிபட வேண்டும்.",
        '0.23': "உலகில் ஜீவர்கள் எப்போதும் இரு வகையினர்: க்ஷரர்-அக்ஷரர் (அழிவுடையவர்-அழிவற்றவர்), லிங்கமற்றவர்-லிங்கமுடையவர், ஸ்ருஜ்யர்-அஸ்ருஜ்யர் என்ற பேதத்தால். ஜடப் பிரகிருதி ப்ரணவம், அக்ஷரம், மஹத், அணு, காலம் முதலிய பெயர்களால் அழைக்கப்படுகிறது. ஹரியுடன் கூடிய ஐந்து பேதங்களை (பஞ்சபேதம்) எங்கும் நினைத்துக்கொள்.",
        '0.24': "ஜீவன்-ஜீவன் பேதம், ஜடம்-ஜடம் பேதம், ஜீவன்-ஜடம் பேதம், பரமாத்மா ஜீவன், ஜடம் இரண்டுக்கும் வேறுபட்டவன் (ஹரி-ஜீவன், ஹரி-ஜடம் பேதங்களுடன் இவை ஐந்து பேதங்கள்) என்று நாளும் அறிந்து, இந்த அண்டத்தில் எங்கும், உடலிலும் ஐந்து பேதங்களை உணர்ந்து அச்சுதனின் திருவடியை விரைவில் அடைவாய்.",
        '0.25': "(இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.) தொடக்கத்தில் க்ஷரம்-அக்ஷரம் என்ற இரு தொகுதிகள் சொல்லப்படுகின்றன; அக்ஷரத்தில் ரமா, மதுசூதனன், க்ஷரத்தில் ப்ரக்ருதி, ப்ரணவம், காலம் குறிப்பிடப்படுகின்றன. பிரம்மா முதல் புல் வரையிலான ஜீவர்களின் பேதங்களை அறிந்து, இந்த ரஹஸ்யத்தை மந்தபுத்தியுடையவர்களுக்குப் போதிக்காமல் எங்கும் சிந்தித்துக்கொள்.",
        '0.26': "விளக்கிலிருந்து ஏற்றிய விளக்குகள் கடையிலுள்ள இருளை நீக்கி அங்குள்ள பொருட்களைக் காட்டுவதுபோல், கருடவாகனனான ஹரி பல வடிவங்கள் பெயர்களால் எங்கும் வியாபித்து, தெரிவிக்காமலேயே தனக்கு வேண்டிய அளவு மகிமையைக் காட்டுகிறான்.",
        '0.27': "சூரியனுக்கு எதிரே வானவில் பிரதிபலிப்பதுபோல், மூவுலகங்களும் எந்த உபாதியும் இன்றி ஹரியில் பிரதிபிம்பமாக (மூல பிம்பத்தின் நிழலாக) தோன்றுகின்றன. இவ்வாறு அறிந்து, எல்லா இடங்களிலும் இதயத்தில் ஒளிரும் ப்ரஹ்லாதனைக் காத்தவனின் மிக மங்கலமான உருவத்தை நாள்தோறும் தியானி.",
        '0.28': "ஒரு சிறப்புச் சாற்றில் மிகத் தூய வெள்ளைத் துணியை நனைத்துத் தீயில் இட்டால் ஒளி மங்காமல் எங்கும் பரவுவதுபோல், த்ரிசிரன், தூஷணன் ஆகியோரின் பகைவனான ராமனின் பக்தி ரஸத்தில் நனைந்த மஹாத்மாக்களை, சம்சாரத்தில் இருந்தாலும், பாவக்குவியல்கள் பாதிப்பதில்லை.",
        '0.29': "ஆறுகள் தனித்தனியாக இடைவிடாமல் கடலில் கலந்து பரம மகிழ்ச்சியுடன் இருப்பதுபோல், முக்குணங்களுக்கும் அபிமானியான ஸ்ரீரமையின் வடிவங்கள் ஹரியில் எல்லாக் காலத்திலும் ஒன்றுக்கொன்று முரண்படாமல் தோன்றுகின்றன.",
        '0.30': "தாமரையின் நண்பனான சூரியன் உதிக்கும்போது ஆந்தை அவனைக் கண்டு மகிழாவிட்டால் சூரியன் குற்றமுடையவனா? அதுபோல் லக்ஷ்மிபதி ஜகந்நாதன் இருக்கும்போது அவனை ஏற்று மகிழத் தெரியாத அறிவிலிகள் நிந்தித்தால் என்ன? இக்கவிதையைக் கேட்டு அறிஞர்கள் மகிழ மாட்டார்களா?",
        '0.31': "குருவான வாயுவின் அந்தராத்மாவான ஜகந்நாத விட்டலன் உயிருள்ளவை உயிரற்றவை எல்லாவற்றிலும் இடைவிடாது வியாபித்து, தன்னைத் தெரிவிக்காமல், விஷயங்களில் ஆவலை எழுப்பி அரக்கர்களை மயக்குகிறான்; அவன் அச்சமற்றவன், நித்திய ஆனந்தமயன், குற்றமற்றவன், பழிக்கப்படாதவன். (வாக்கியம் முடிவுபெறாமல் நிற்கிறது.)",
      },
    },
    'harikathamrutasara-15': {
      summary: "பதினைந்தாம் ஸந்தி (ஶ்வாஸம்): பாரதீபதியான வாயு எல்லா உயிர்களுக்குள்ளும் இருந்து ஹரியின் ஆணையால் நாளொன்றுக்கு இருபத்தோராயிரத்து அறுநூறு மூச்சு ஜபங்களை (ஒவ்வொரு நாழிகைக்கும் முந்நூற்று அறுபது) செய்கிறான்; ஜாமம், பக்ஷம், மாதம், ருது, வருடம் ஆகியவற்றுக்கு அவற்றின் கணக்கை இந்த ஸந்தி தருகிறது. இதை அறியாமல் செய்யும் வெறும் சடங்குகள் பயனற்றவை. ஹரி அன்னம், நீர், நெருப்பில் உறைவது, முக்தர்கள் ஹரியின் நகரத்தை பல தேவர்கள் காக்கும் ஐந்து வாயில்கள் வழியாக அடைவது, உலகம் ஹரியின் பிரதிபிம்பம் என்பது, அவனது ஒரு குணத்தையாவது பக்தியுடன் உபாசித்தால் கிருதார்த்தம் கிடைக்கும் என்பது ஆகியவற்றையும் இது கூறுகிறது.",
      verses: {
        '0.0': "குருவின் கருணையால் ஹரிகதாம்ருதஸாரத்தைச் சொல்கிறேன்; பரம பகவத்பக்தர்கள் இதை ஆதரவுடன் கேட்க வேண்டும்.",
        '0.1': "பாரதீசனான வாயு எல்லா உயிர்களுக்குள்ளும் இருந்து சலிப்பின்றி ஒவ்வொரு நாழிகையிலும் (24 நிமிடம்) முந்நூற்று அறுபது ஜபங்களைச் செய்கிறான். கருணையுள்ளவன், எல்லாம் அறிந்தவன், எல்லா விருப்பங்களையும் அளிப்பவன் ஆன அவன் ஒவ்வொருவரின் ஸாதனையையும் நிறைவேற்றி பூமி, சொர்க்கம், நரகம் ஆகியவற்றில் சேர்க்கிறான்.",
        '0.2': "(பாடல் முடிவுறாமல் நிற்கிறது.) உயிர்த்திரள்களிடையே இரவும் பகலும் விழிப்புடன் இயக்கி, சிறிதும் களைப்பின்றி அவற்றைப் போஷித்து, மூலேசனின் திருவடித்தாமரையின் வேரடியில் யாருக்கும் தெரியாமல் இருக்கிறான்.",
        '0.3': "ஒரு ஜாமத்தில் (மூன்று மணி) 2,700 மூச்சுகள்; இரண்டு ஜாமங்களுக்கு 5,400; மூன்று ஜாமங்களுக்கு 8,100; பன்னிரண்டு மணிக்கு 10,800 என்று அறிய வேண்டும்.",
        '0.4': "ஒரு நாளில் மொத்தம் 21,600 ஆகும். முகுந்தனின் ஆணையால் வாயு இவற்றைத் தானே செய்தும் செய்விக்கவும் செய்து உலகங்களைக் காக்கிறான் என்று அவனை எப்போதும் மறவாமல் புகழ்ந்துகொண்டிரு. இந்திரன் முதலியோருக்கு இந்த மகிமை எக்காலத்திலாவது உண்டா, பார்த்தால்?",
        '0.5': "ஒரு பக்ஷத்துக்கு 3,24,000, ஒரு மாதத்துக்கு 6,48,000 ஜபங்களைச் செய்து மாருதன் நல்லோரை சம்சாரக்கடலிலிருந்து கடக்கச்செய்து பல போகங்களை அளித்துக் காக்கிறான். (கடைசிச் சொல் முடிவுபெறவில்லை.)",
        '0.6': "இரண்டு மாதம் கொண்ட ஒரு ருதுவுக்கு 12,96,000 மூச்சு ஜபங்கள் என்று அந்தணர் அறிய வேண்டும்; அயனத்துக்கு (ஆறு மாதம்) 38,88,000 என்று அறிஞர் அறிவர்.",
        '0.7': "ஒரு வருடத்துக்கு இதன் இரு மடங்கு ஜபங்களை குருவான வாயு தானே செய்தும் செய்விக்கவும் செய்து, நினைக்கும் நல்லோரின் பாவங்களை நீக்குகிறான். தேவர்களின் பகைவர்களான தமோயோக்யர்களுக்குள்ளும் இருந்து, அவர்களின் நிலையை அறிந்து அவர்களைப்போலவே 'ஸோஹம்' உபாசனையைச் செய்கிறான்.",
        '0.8': "வாயுதேவன் எல்லா உயிர்களுக்குள்ளும் இவ்வளவு உபாசனை செய்துகொண்டிருக்கும்போது, இதைச் சிந்திக்காமல் கண்ட நீரில் மூழ்கி, வீட்டில் கிருஷ்ணாஜினம் முதலிய ஆசனத்தில் அமர்ந்து, சிறந்த நல்லவன் என்று பெயர் பெற்று சலிப்பின்றி ஜபமணிகளை எண்ணினால் என்ன பயன்?",
        '0.9': "(பிரளயம் பற்றியது.) அன்னம், நீர் இரண்டும் தேஜஸில் லயமாகின்றன; அவற்றின் அபிமானிகளான சிவனும் வாயுவும் ரமையின் அதீனத்தை அடைகிறார்கள். அவள் இந்த தேவர்களுடன் ஸ்ரீமதுசூதனனை அடைகிறாள். இதை அறிந்து ஆதரவுடன் அன்னமும் நீரும் அளித்து உண்டு மகிழ்ந்திரு.",
        '0.10': "கருவேல இலைகளைத் தின்ற ஆடு, செம்மறிகள் தம் விருப்பப்படி பால் தருவதுபோல், லக்ஷ்மீரமணன் தன்னவர்களின் தாழ்ந்த செயலையும் ஏற்று, தன் இல்லத்தில் வைத்தவர்களைக் காக்கிறான்; அவன் கருணையுள்ள, நீலோற்பலம்போல் கருமை நிறமுடைய ஸ்ரீராமன்.",
        '0.11': "(இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.) சந்திரன், சூரியன், அக்னி ஆகியவற்றிலுள்ள கருப்பு, வெள்ளை, சிவப்பு வடிவங்களில் சிவன், வாயு, லக்ஷ்மி இருக்கிறார்கள்; இம்மூவருக்குள் ஸ்ரீகிருஷ்ணன், ஹயவதனன். கருணையுள்ள அவன் த்ரிவ்ருத்தாகி பூமியில் அன்னம், உதகம், அனலம் என்ற பெயர்களால் எல்லா உயிர்களையும் காக்கிறான்.",
        '0.12': "(பாடல் முடிவுறாமல் நிற்கிறது.) கையில் விளக்கை ஏந்தியும் காணாமல் கிணற்றில் விழுந்தவனைப்போல், வேதங்கள், மஹோபநிஷத்துகளின் பொருளை நாளும் சொல்பவர்கள் அனைவரும், ஸ்ரீயாலும் வாயுவாலும் துதிக்கப்படும் ஹரியின் தூய வடிவங்களின் செயலை அறியாமல், பாவ புண்ணியங்களுக்கு ஜீவனே கர்த்தா என்கிறார்கள்; உண்மையான கர்த்தா ஹரியே.",
        '0.13': "வாயுதேவன் வாக்கும் மனமுமாகி அக்னி, வருணன், இந்திரன் முதலியோருக்குள் இருந்து பகவானின் ரூபகுணங்களை மீண்டும் மீண்டும் நினைத்து உச்சரித்து நம்மை எப்போதும் தேற்றுகிறான்; அவனது திருவடித்தாமரைகளை முனிவர் கூட்டங்கள் ஆராதிக்கின்றன.",
        '0.14': "வாக்கு, மனம் என்ற இரண்டு வடிவங்களே அவனது பாதங்கள் எனப்படுகின்றன; அவற்றில் ப்ரஹ்லாதனைக் காத்தவன் ஸங்கர்ஷணன் என்ற பெயரில் இருந்து, வேத சாஸ்திர புராணங்களை உரையாடல் வடிவில் மனனம் செய்து, ஆனந்த சுகத்தை அளித்து எல்லா நல்லோரையும் காக்கிறான்.",
        '0.15': "காற்று பத்துத் திசைகளிலும் தாமரையின் மணத்தைப் பரப்பி மூக்குக்கு இன்பம் தந்து சஞ்சரிப்பதுபோல், இந்திரேசனின் நற்குணங்களை நாள்தோறும் துதித்து மகிழ்; அறிவிலிகளுடன் குருடன், செவிடன், ஊமையைப்போல் இரு.",
        '0.16': "ஸ்ரீரமணனின் அரண்மனையின் கிழக்கு வாயிலில், ஸஞ்ஜ்ஞையின் கணவன் சூரியன் இருக்கும் இடத்தில், பாரதீபதியான ப்ராணனுக்குள் இருக்கும் லக்ஷ்மிநாராயணனை அடைந்து, மனிதரில் சிறந்தோர் எல்லா உடல்களிலும் இருக்கும் நாராயணனின் அவதாரங்களையும் குணங்களையும் துதித்து முக்தியில் மகிழ்கிறார்கள்.",
        '0.17': "ப்ரணவத்தால் விளக்கப்படும் ஹரியின் நகரத்தின் தெற்கு வாயிலில், சந்திரனும் ரோஹிணியும் இருக்கும் இடத்தில், வ்யானத்தில் உறையும் கிருதியுடன் கூடிய ப்ரத்யும்னனின் ரூபகுணங்களைத் துதித்து பித்ருகணங்கள் கதாதரனின் மிகத் தூய நகரத்தில் தம் விருப்பப்படி சஞ்சரிக்கின்றனர்.",
        '0.18': "(இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.) மிதவிக்ரமனின் ஆலயத்தின் மேற்கு வாயிலில் ரிஷிகள் மனைவியருடன் மகிழ்ச்சியுடன் பகவானின் குணங்களைப் புகழ்ந்து தேவர்களை மகிழ்விக்கிறார்கள்; தம் இதயத்தாமரையில் ஸங்கர்ஷணனை தியானித்து சுகிக்கிறார்கள்.",
        '0.19': "ஸ்ரீரமணனின் குணரூபங்களை ஏழு ஸ்வரங்களால் பாடும் தும்புரு முதலிய எல்லா கந்தர்வர்களும், ரமாபதியின் நகரத்தின் வடக்கு வாயிலின் அதிபர்களான இந்திரன்-சசியுடன், ஸமான வாயுவில் உறையும் மரகதமணிபோல் பசுமை ஒளியுடைய சாந்திபதி அநிருத்தனை அடைகிறார்கள்.",
        '0.20': "கருடன், சேஷன், தேவேந்திரன் முதல் புஷ்கரன் வரையிலான எல்லா தேவர்களும் ஊர்த்வ வாயிலில் இருந்து, உதானத்தில் உறையும் பாரதியுடன் அங்கு விளங்கும் மாயாவாசுதேவனின் பரம மங்கல உறுப்புகளின் ஆலயத்தை அடைந்து எப்போதும் முகுந்தனைக் கண்டு மகிழ்கிறார்கள்.",
        '0.21': "ஐந்து வாயில்களின் காவலர்களுக்குள்ளும் பாரதீ-ப்ராணர்களுக்குள்ளும் அந்தராத்மாவான ரமாரமணன் அந்தந்த வாயிலில் ஐந்து வடிவங்களில் வருகிறான். முக்திக்குத் தகுதியான ஐவகையினரின் தாரதம்யத்தை (உயர்வு தாழ்வு வரிசையை) அறிந்தவர்களை கம்ஸாரி சம்சாரக்கடலைக் கடக்கச்செய்து முக்தராக்குகிறான்.",
        '0.22': "மெருகிட்ட பாத்திரம் பார்ப்பவருக்குப் பளபளப்பதுபோல், உடலைக் கழுவி நாமமுத்திரைகளால் அலங்கரித்து ஹரியை நாளும் மகிழ்விப்பாய். தவறான வாதங்களாலும் அறிவிலிகளின் தர்க்கங்களாலும் சாஸ்திரத்தின் மர்மத்தை அறியாத மனிதன் வெறுமனே இதில் சந்தேகித்தால் என்ன பயன்?",
        '0.23': "கடலில் அலைகள் தோன்றுவதுபோல், ஹம்ஸ, உத்கீத, ஹரி, ஹயவதன, கிருஷ்ண முதலிய எண்ணற்ற அவதாரங்கள் பத்மநாபனிடம் நித்தியமாக உள்ளன; எல்லா உயிர்களின் சித்-இதயத்தில் உள்ள வடிவங்களும் அவனிடம் இடைவிடாது உள்ளன.",
        '0.24': "கடலில் முதலை முதலிய உயிர்கள் இரவும் பகலும் ஒரே விதமாகச் சஞ்சரித்து மகிழ்வதுபோல், மூவுலகங்களும் ஜகதீசனின் வயிற்றில் உள்ளன; அவை பிரதிபிம்பம் எனப்படுகின்றன, ஹரியின் நாமரூபங்களை எப்போதும் தாங்கியிருக்கின்றன.",
        '0.25': "தாய் சிறந்த உணவுகளை உண்ணும்போது கருவிலுள்ள சிசு நாளும் வளர்வதுபோல், தாமரை நாபியன் ஜீவர்களுக்கு எல்லாச் சுவைகளையும் ஊட்டிக் காக்கிறான்; கங்கையின் தந்தையான அவன் பிறப்பு முதலிய எல்லாக் குற்றங்களுக்கும் தொலைவானவன், ஆழ்ந்தவன்.",
        '0.26': "ஆசைக்கு அடிமையானவன் மக்களுக்குத் தாசனாகிறான்; ஆசையைத் தன் தாசியாக்கிக் கொண்ட மனிதனுக்கு எல்லோரும் தாசர்களாகிறார்கள். ஸ்ரீசனின் திருவடித்தாமரைகளை ஆசையின்றி வழிபட்டால் கருணைக்கடலான ஹரி மகிழ்ந்து ரமையுடன் தன்னையே அளிக்கிறான்.",
        '0.27': "கங்கையின் தொடக்கத்தையும் முடிவையும் காணாமலேயே மனிதன் ஓரிடத்தில் நீராடினாலும் எல்லாக் குற்றங்களிலிருந்தும் விடுபடுவதுபோல், பாவமற்றவனின் எல்லையற்ற நற்குணங்களுள் ஒரு குணத்தையே உபாசிக்கும் மகாத்மா பாக்கியவான், கிருதார்த்தன் எனப்படுகிறான்.",
        '0.28': "(பாடல் முடிவுறாமல் நிற்கிறது.) வாசுதேவன் பருத்திச் செடி என்று அழைக்கப்படுகிறான்; அதன் பஞ்சில் ஸங்கர்ஷணன், நூலில் ப்ரத்யும்னன், ஆடை வடிவில் அநிருத்தன், ஆபரணமாகத் தோன்றுபவன் பரேசன் நாராயணன்; அவன் எப்போதும் மதிக்கத்தக்கவன், மதிப்பளிப்பவன்.",
        '0.29': "நான்கு வடிவினனான ஜகந்நாத விட்டலன் மனைவியுடன் ஆடைகளில் நீளவாட்டு குறுக்கு நூல்கள்போல் நிலைத்திருக்கிறான். குளிர், வெயில், மழை, காற்று ஆகியவற்றிலிருந்து அரை நாழிகையும் விடாமல் காக்கிறான் என்று அறிந்து, எல்லோருக்கும் அந்தராத்மாவான அவனை இந்த பூமியில் எப்போதும் அர்ச்சித்துக்கொண்டிரு.",
      },
    },
    'harikathamrutasara-16': {
      summary: "பதினாறாம் ஸந்தி (தத்தஸ்வாதந்த்ரியம்): ஹரி ஒருவனே முழு சுதந்திரன்; தன் சுதந்திரத்திலிருந்து அளவிட்ட பங்கை லக்ஷ்மி, பிரம்மா, வாயு முதல் அசுரர்கள் வரை எல்லோருக்கும் அவர்களின் தாரதம்யத்துக்கேற்ப அளித்து, அவர்கள் மூலம் செயல்களை நடத்துகிறான். ஜீவர்களை அவர்களின் தகுதி, கர்மத்துக்கேற்ப நடத்துகிறான்; பக்தியற்றவர்களின் நற்செயல்களை எடுத்து சரணடைந்தவர்களுக்கு அளிக்கிறான்; தன் அதீனத்தை ஏற்றவர்களை சம்சாரக்கடலைக் கடக்கச்செய்கிறான். 'நானே சுதந்திரன்' என்பவனின் வாதம் இங்கு கேலி செய்யப்படுகிறது. மக்கள் மொழியில் பக்திக் காவியம் இயற்றுவதன் நியாயமும் கவியின் பணிவும் கூறி ஸந்தி முடிகிறது.",
      verses: {
        '0.0': "குருவின் கருணையால் ஹரிகதாம்ருதஸாரத்தைச் சொல்கிறேன்; பரம பகவத்பக்தர்கள் இதை ஆதரவுடன் கேட்க வேண்டும்.",
        '0.1': "(இப்பாடலிலுள்ள எண்கள் தெளிவற்றவை.) கருணையுள்ள ஹரி தன்னுள் இருக்கும் அளவற்ற சுதந்திரத்திலிருந்து ஒரு பங்கை எடுத்து லக்ஷ்மிக்கு குறிப்பிட்ட பங்கை அளித்து, தன் உடலுக்குள் உள்ள மூன்று பாதங்களை இவ்வாறு பகுத்தான்; ஆகவே அவன் த்ரிபாதன் எனப்படுகிறான்.",
        '0.2': "குற்றமற்ற ஹரி ஸத்யலோகாதிபதியான பிரம்மாவிடம் ஐம்பத்திரண்டு, வாயுவிடம் நாற்பத்தெட்டு, சிவனிடம் இருபது, காமன் இந்திரனிடம் பதினைந்து, தத்துவ அபிமான தேவர்களிடம் பத்து, மற்ற எல்லா ஜீவர்களிடமும் பத்து பங்குகளை வைத்தான்.",
        '0.3': "கலி முதலிய எல்லா அசுரர்களிடமும் நாற்பத்தைந்து பங்குகளை வைத்தான். இதை அறிந்து பரம பக்தியுடன் மறவாமல் உபாசி. லக்ஷ்மிநிலயன் எல்லா இடங்களிலும் நண்பனைப்போல் தேற்றிக்கொண்டிருக்கிறான் என்று அறிந்து பூமியில் சஞ்சரி.",
        '0.4': "அரசன் தன் அதிகாரத்தையும் உடைமையையும் தன் அதீனத்திலுள்ள அமைச்சர்களுக்கு அளித்து அவர்கள் மூலம் அரசுப்பணி செய்விப்பதுபோல், கவிஞர்களால் துதிக்கப்படும் ஹரி தன் கலைகளை தேவர், அசுரர், மனிதர்களிடம் வைத்து முக்குணங்களால் பிறக்கும் செயல்களை இடைவிடாது செய்தும் செய்வித்தும் வருகிறான்.",
        '0.5': "இவ்வாறு கருணைக்கடல் தேவர், அசுரர், மனிதர்களிடம் புண்ணிய பாவங்களை வைத்து அவர்களின் பலன்களை மாற்றி நடத்துகிறான்; பக்தியற்றவர்களின் புகழப்படும் நற்செயல்களை எடுத்து சரணடைந்தவர்களுக்கு அளித்து அவர்களை மகிழ்விக்கிறான்; அவன் சுபுஜன்.",
        '0.6': "கடையில் மாணிக்கத்தைப் பெற்ற வணிகன் கொடுத்தவனுக்கு ஏதோ சிறு பொருளைக் கொடுத்துச் சமாதானப்படுத்துவதுபோல், தைத்தியர்கள் நாளும் செய்யும் தானம், யஜ்ஞம் முதலியவற்றின் பலனை எஜமானனான ஹரியே எடுத்துக்கொண்டு, அவர்களுக்குத் தகாத சுகங்களை அளித்து அசுரர்களை மயக்கத்தில் ஆழ்த்துகிறான்.",
        '0.7': "மான் அடையாளமுடைய சந்திரனின் தூய கிரணங்கள் படிப்படியாக வளர்ந்து மக்கள் பார்க்கவிடாமல் தடுக்கும் இருளை அழிப்பதுபோல், கருடனின் தோளிலுள்ள ஹரியின் மூர்த்தியைத் தியானிக்கும் மஹாத்மாக்களிடம் ஞானமும் பக்தியும் வளர்ந்து சுகம் அளிக்கின்றன.",
        '0.8': "அரசன் நகரில் செல்வத்தைத் திருடி வந்து ஒப்படைத்த திருடனின் குற்றங்களை எண்ணாமல் அவனைக் காப்பதும், ஒப்படைக்காதவனைத் தண்டிப்பதும்போல், தகுந்த தகாத செயல்களை 'கிருஷ்ணார்ப்பணம்' என்று அர்ப்பணித்தால் அவற்றை ஏற்று, அர்ப்பணித்தவனைத் தன் இல்லத்தில் வைத்து மகிழ்விக்கிறான் மாதவன், வணங்கியவர்களுக்கு அன்பானவன்.",
        '0.9': "முன்பு கூறியபடி அன்னம், அன்னாதன் என்ற பெயர்களால் ஹரி அன்ன வடிவில் ஜீவர்களுக்குள் புகுந்து, அவரவர் செயல்களைத் தான் துன்புறாமல் செய்தும் செய்வித்தும், அவர்களை பாக்கியசாலிகள் என்று புகழச்செய்து, முக்குணங்களற்றவனாயினும் அந்தந்தப் பெயர்களால் அழைக்கப்படுகிறான்.",
        '0.10': "(கடைசி வரி முடிவுறவில்லை.) நீர் விழுந்த பொருளின் வடிவையே பெறுவதுபோல், கலியின் மாசை நீக்கும் ஹரியை அர்ச்சிக்கும் நற்குலத்தோரின் தீய செயல்களும் குற்றமற்ற செயல்களாகி புருஷார்த்தங்களை அளிக்கின்றன.",
        '0.11': "தாய் குழந்தையின் முகத்தில் முகம் வைத்து முத்தமிட்டு, இறுக அணைத்து, அன்புடன் தன் மார்பை எடுத்து ஊட்டுவதுபோல், அளவற்ற ஆத்மாவான ஹரி தன் திருவடித்தாமரைகளைத் தியானிக்கும் பக்தர்களுக்குத் தானே துணையாகி எங்கும் சுகங்களை அளிக்கிறான்.",
        '0.12': "தோட்டக்காரன் மண்ணில் விதை வேரூன்ற வேண்டும் என்று அன்புடன் குடத்தால் நீர் இறைத்து செடிகளைப் பேணுவதுபோல், குதிரைமுகன் ஹயக்ரீவன் சிரமமின்றி உலகில் ஜீவர்களைப் படைத்து, அவர்களின் தகுதியைக் கடக்கவிடாமல் எல்லாக் காலத்திலும் காக்கிறான்.",
        '0.13': "நிலத்தில் நீர் இருந்தும் தாகமுள்ளவன் அதை மறந்து முகத்தை உயர்த்தி எட்டுத் திசை வானத்தில் தேடி காணாமல் தவிப்பதுபோல், ஸ்ரீமனோரமனே எல்லோருக்கும் அந்தர்யாமி என்று அறியாத மயங்கியவர்கள் நாள்தோறும் பக்தியுடன் பிற தேவர்களை வழிபடுகிறார்கள்.",
        '0.14': "முக்கிய பலன் வைகுண்டம்; இடைப்பட்ட பலன் மஹர் முதலிய உலகங்கள்; முக்கியமற்ற பலன் விஷய இன்பம் என்று அறிந்து, மிகுந்த பக்தியுடன் ராக்ஷஸாரியை வழிபட்டு எப்போதும் துன்பமற்றவனாகு. பக்தவத்ஸலனும் பாரதீசனின் தந்தையுமான ஹரி சரணடைந்தவர்களை விடமாட்டான்.",
        '0.15': "(பாடலின் முடிவு முழுமையற்றது.) நோயால் வருந்தும் குழந்தைக்குத் தாய் வெல்லநீரையும் நீரில் அரைத்த மருந்தையும் புகட்டுவதுபோல், எல்லாம் அறிந்த பாதராயணர் பக்தர்கள்மீது கருணையால் பாகவதம் முதலியவற்றில் தர்மம் முதலியவையே பலன் என்று கூறினார்.",
        '0.16': "தொலைவிலுள்ள மலை பார்ப்பவர்களுக்குப் பெரிதாகத் தெரியும்; அருகில் சென்றால் பாம்பு, புலி ஆகியவற்றால் பயம் உண்டு. அதுபோல் சம்சார சுகம் பயங்கரமானது, சாரமற்றது என்று அறிந்த ஞானிகள் நாளும் ரமாரமணனை ஆராதிக்கிறார்கள்.",
        '0.17': "பச்சை மண் குடங்களைச் செய்து கோடை வெயிலில் உலர்த்தினால் அவற்றில் கெட்டியான சாற்றை நிரப்ப முடியுமா? 'நான் முழு சுதந்திரன்' என்னும் பசுவைப் போன்றவனுக்கு உணவு, தானம், நீராடல் முதலிய செயல்கள் என்ன செய்யும்? அவை கசிந்து போய் வெறும் உடல் களைப்பையே தருகின்றன.",
        '0.18': "இரண்டு தீட்சைகள் உள்ளன, வெளி, உள் என்ற பெயருடையவை; அறிஞர்களிடம் அறிந்து தீட்சை பெறு. நீண்ட பகைகளை விட்டு, ஹரியே எல்லோரினும் உயர்ந்தவன், க்ஷர-அக்ஷர புருஷர்களால் வணங்கப்படும் திருவடியுடையவன், பிறப்பு முதலியவற்றிலிருந்து தொலைவானவன், இன்பவடிவினன், எங்கும் நிறைந்தவன் என்று நினைத்துக்கொண்டிரு.",
        '0.19': "தாமரைக்கண்ணனுக்கு விடவேண்டிய பொருள்கள் இல்லை, ஏற்க வேண்டிய பொருள்கள் இல்லை, நியாய அநியாய தர்மங்கள் இல்லை, பகை பொறாமை முதலியவை இல்லை, தாய் தந்தையர் இல்லை. நீந்துபவனுக்குத் துணையாகும் சுரைக்காய்போல் மூழ்கவிடாமல் சம்சாரக்கடலைக் கடக்கச்செய்கிறான்.",
        '0.20': "(பாடல் முடிவுறாமல் நிற்கிறது.) மந்தபுத்தியுடையவனாயினும் மகிழ்ச்சியுடன் கோபீசந்தனம், ஸ்ரீமுத்திரைகளை அணிந்து, துளசி, தாமரைக்கண் மாலைகளைக் கழுத்தில் அணிந்து, 'ஸ்ரீ-பூரமணனான முகுந்தன், மூவுலகினும் வணங்கத்தக்க ஸர்வஸ்வாமி என் குலதெய்வம்' என்றால் அவன் காக்கிறான்.",
        '0.21': "(இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.) மனிதனின் 'பிரபுத்வம்' என்ற கூற்றை இப்பாடல் கேலி செய்கிறது: தாயின் கருவில் இருந்தபோது அவனை யாரும் பிரபு என்று அழைக்கவில்லை; உடல் அவனை விட்டுப் போனால் 'நீ அரசன்' என்று அழைக்கும் பிரபுத்வம் ஓடிவிடுகிறது; அருகில் இருக்கும்போதுதான் அது தெரிகிறது.",
        '0.22': "வாசுதேவனே ஈசன் என்ற முறையில், ஈசர் எனப்படும் பிரம்மா, ருத்ரன், இந்திரன் முதலிய எல்லா தேவர்களும் அவனுடைய தாசர்கள் எனப்படுகிறார்கள். இந்த நல்வழியை விட்டு 'ஸோஹம்' உபாசனை செய்யும் மனிதன், உடலால் விதியால் வரும் துன்பங்கள் வரும்போது அவற்றிலிருந்து ஏன் தன்னை விடுவித்துக்கொள்வதில்லை?",
        '0.23': "அந்தப் பரப்பிரம்மனிடம் மூவுலகிலும் வியாபித்தல், நியமித்தல், நிலைநிறுத்தல், வசப்படுத்தல், ஈசத்வம் முதலிய குணங்களுக்குக் குறைவில்லை; அவை ஒரே விதமாக அவனது ஸ்வரூபமாகி எக்காலத்திலும் அவனை விட்டுப் போவதில்லை, ஜீவர்களை தாசத்வம் விட்டுப் போகாததுபோல்.",
        '0.24': "நித்திய புதியவன், மாறாதவன், சிறந்த நண்பன், ப்ரணவத்தில் இருப்பவன், எழுத்துகளின் தோற்றத்துக்குக் காரணன், வாக்கும் மனமுமானவன், ஸாமகானப்ரியன் ஆன ஹரி தத்தர், கபிலர், ஹயக்ரீவர் வடிவங்களில் தனித்தனியாக ஜீவர்களுக்குள் இருந்து அவரவர் தகுதி, கர்மத்தை அனுசரித்து நடத்துகிறான்.",
        '0.25': "ஸ்ருதிகள் அவனது சொற்கள், தூய ஸ்ம்ருதிகள் அவனது போதனை; ஜீவ கூட்டமும் ப்ரக்ருதியும் இரண்டும் அவனது பிரதிமைகள் எனப்படுகின்றன. மற்ற எல்லாச் செயல்களும் லக்ஷ்மீபதிக்குச் செய்யும் பூஜைகள் என்று நினைத்து, நான்கு புருஷார்த்தங்களையும் கனவிலும் கேட்காதே.",
        '0.26': "அரசன் தன் ஆணையைச் சுமக்கும் தூதர்களுக்குச் சேவைக்கேற்ப ஊதியம் கொடுத்து மகிழ்விப்பதுபோல், வாயுப்ரியனான ஹரி மிகுந்த அன்புடன் தன் நற்குணங்களைப் பற்றியவர்களை இம்மையிலும் மறுமையிலும் மகிழ்விக்கிறான்.",
        '0.27': "(முதல் இரண்டு வரிகள் தெளிவற்றவை.) பகலில் விளக்கு தென்பட்டால் மக்கள் அதை அக்கணமே அணைத்துவிடுவர்; ஹரி அருகில் இருக்கும்போது ... இது வெறும் உபசார மொழி அல்ல: நல்லோரின் பாவச்செயல் புண்ணியமாகிறது; பாவிகளின் நற்புண்ணியச் செயல் பாவமாகிறது.",
        '0.28': "செல்வம் ஈட்டும் வணிகர்களைப்போல் சாஸ்திரம் கேட்பதற்காக அறிஞர்களின் இல்லங்களுக்குச் செல்; சிந்தித்து உபதேசி; தீயவர்களுடன் கனவிலும் சேராதே. வணங்கியவர்களின் விருப்பங்களை அவன் இம்மையிலும் மறுமையிலும் சுகம் அளித்து நிறைவேற்றுகிறான்.",
        '0.29': "காரகம் (கர்த்தா), கிரியை, திரவியம் ஆகியவற்றைப் பற்றிய மயக்கம் மூவகை ஜீவர்களுக்கும் மிகுந்த சம்சாரத்துக்குக் காரணமாகிறது. எல்லாக் காலத்திலும் இவற்றை விரட்டி, இம்முன்று மயக்கங்களுக்கு இரையாகாமல், எல்லாவற்றுக்கும் ஆதாரமானவனை எங்கும் மறவாமல் சிந்தித்துக்கொண்டிரு.",
        '0.30': "'நானே சுதந்திரன்' என்பவன் உண்மையில் சுதந்திரனாக இருந்தால், மறதி (உறக்க) நேரத்தில் பேசினால் பதில் சொல்லாமல் ஏன் அமைதியாக இருக்கிறான்? விழிப்பு நிலையில் ஹரி கருணை புரியும்போதுதான் செயல்படுகிறான்; நான்கு நிலைகள் வரும்போது அவற்றை ஏன் தவிர்த்துக்கொள்வதில்லை?",
        '0.31': "இவை வெறும் யுக்திப் பேச்சுகள் அல்ல; ஸ்ருதி ஸ்ம்ருதிகள் கூறிய சொற்கள்; ஆராய்ந்தால் இவை முக்திக்குப் படிகள். ஒவ்வொரு பதத்தையும் பக்தியுடன் படிப்பவர்களுக்குப் பலவடிவினனான ஹரி ஸ்வரூப சுகத்தின் வெளிப்பாட்டை அளித்து சம்சார பயத்திலிருந்து விடுவிக்கிறான்.",
        '0.32': "(இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.) ஸ்ரீநிவாஸனின் நற்குணங்கள் என்னும் மணிகளை ப்ராணமதம் (வாயுவின் கோட்பாடு) என்ற நூலில் கோர்த்து சொல்மாலையாக அர்ப்பணித்தது, அறிவிலிகளின் கண்ணில் பட்டால் மாணிக்கத்தைக் குரங்கின் கையில் கொடுத்தது போல் தகாததாகத் தோன்றும்.",
        '0.33': "ஸ்ரீ, பிரம்மா, ருத்ரன், சேஷன், இந்திரன், காமன், சூரியன், சந்திரன், திக்பாலர்கள், ரிஷிகள், கந்தர்வர்கள், கின்னரர்கள், சித்தர்கள், சாத்யகணங்கள் ஆகியோரால் வணங்கப்படும் திருவடித்தாமரை உடையவனே, உன் திருவடிகளைச் சார்ந்த பக்தர்களைக் காப்பவனே, கருணை நிறைந்தவனே, லக்ஷ்மியின் இதயமாகிய ஆம்பலுக்குச் சந்திரனே!",
        '0.34': "கண்ணாடியை வேறு மொழிப் பெயரால் அழைத்தார்கள் என்பதற்காக அதைப் பார்க்காமல் விவேகிகள் விட்டுவிடுவார்களா? மாதவனின் குணங்களைக் கூறும் காவியம் மக்கள் மொழியில் இருந்தாலும் அதைக் கேட்டு அறிந்த ஞானிகள் பேரானந்தம் அடையாமல் இருப்பார்களா?",
        '0.35': "சூரிய மண்டலத்தைக் கண்டு வணங்கி மகிழாமல் பகையால் திருடன் நிந்தித்தால் சூரியனுக்குக் குறை உண்டா? இது சம்ஸ்கிருதம் அல்ல என்று கபடன் புறக்கணித்தால் என்ன ஆகும்? பக்தியை முன்னிட்டுக் கேட்பவர்களுக்குப் புஷ்கராக்ஷன் எப்போதும் மனமகிழ்கிறான்.",
        '0.36': "தாழ்ந்தவனின் மண்டையோட்டில் கங்கை நீர் இருந்தால் அது குடிக்கத் தகுந்தது எனப்படுவதில்லை; அதுபோல் மற்ற கவிகள் இயற்றிய தீய காவியம் அறிஞர்களுக்குக் கேட்கத் தகாதது. ஆனால் க்ருதிபதியின் கதையைச் சொல்லும் ப்ராக்ருத (மக்கள் மொழி) காவியமே ஸம்ஸ்க்ருதம் (செம்மை) எனப்பட்டு பக்தியுடன் கேட்பவர்களுக்கும் சொல்பவர்களுக்கும் நற்கதியை அளிக்கிறது.",
        '0.37': "நான் வேதங்கள், சாஸ்திரங்கள், தர்க்க நூல்கள் ஆகியவற்றைப் படித்துக் கேட்டவன் அல்லன்; சாதுக்களின் தொடர்ந்த சேர்க்கையும் உரையாடலும் எனக்கு முன்பிருந்தே இல்லை. மத்வாசாரியரின் மதத்தைப் பின்பற்றுபவர்களின் கருணையால், ரமாதவனான ஜகந்நாத விட்டலன் உள்ளிருந்து தெரிவித்ததையே நான் கூறினேன்.",
      },
    },
    'harikathamrutasara-17': {
      summary: "பதினேழாம் ஸந்தி (ஸ்வகதஸ்வாதந்த்ரியம், ஹரியின் சொந்த சுதந்திரம்): பரமவிஷ்ணு ஒருவனே சுதந்திரன்; லக்ஷ்மி அவனது மார்பில் வசிக்கிறாள்; பிரம்மாவும் வாயுவும் அவனது இரு அமைச்சர்கள். தன் சுதந்திரத்தை அளவிட்ட பங்குகளாகப் பிரித்து சிவன், இந்திரன், காமன், இந்திரிய அபிமான தேவர்கள், ஜீவர்கள், கலி முதலிய அசுரர்களுக்கு அளித்து, ஒவ்வொருவருக்கும் செயல் செய்யவும் தம் புண்ணிய பாவங்களை அனுபவிக்கவும் ஆற்றல் தருகிறான். எண்ணற்ற ஜீவர்களுக்குள் இருந்து, ஏரியிலுள்ள தாமரை இலைபோல் ஒட்டாமல் செயல்படுகிறான்; தனக்குச் செயல்களை அர்ப்பணித்தவர்களின் புண்ணியத்தை ஏற்று பாவத்தை எரிக்கிறான். மூலமான விஷ்ணுரஹஸ்யத்தைக் குறிப்பிட்டு, கவியின் மன்னிப்பு வேண்டுதலுடன் ஸந்தி முடிகிறது.",
      verses: {
        '0.0': "குருவின் கருணையால் ஹரிகதாம்ருதஸாரத்தைச் சொல்கிறேன்; பரம பகவத்பக்தர்கள் இதை ஆதரவுடன் கேட்க வேண்டும்.",
        '0.1': "பரமவிஷ்ணுவே சுதந்திரன்; மாயாதருணி லக்ஷ்மி அவனது மார்பில் வசிக்கிறாள்; பிரம்மாவும் வாயுவும் இருவரும் அவனது அமைச்சர்கள், எல்லாச் செயல்களிலும் அவனுக்குப் பிரியமானவர்கள். பாம்பணியணிந்த சிவன் மூவகை அஹங்காரத்தின் அபிமானி; இந்திரன், சூரியன் முதலியோர் இந்திரியங்களின் அபிமான தேவர்கள் எனப்படுகிறார்கள்.",
        '0.2': "இந்த தேவர்களைப்போல் கலி முதலிய தைத்தியர்களும் எல்லா உடல்களிலும் தாமே செயல்களைச் செய்கிறார்கள். பிரம்மாவைப்போல் அஹங்காரத்தின் அதிபனாகி அதமனான கலியும், மது, கைடபன், க்ரோதி, சம்பரன் முதலியோரும் மனதுக்குத் தலைவர்கள் எனப்படுகிறார்கள்.",
        '0.3': "தேவர்களைப்போல் இவர்களும் நாளும் தத்தம் பெயர்களால் எல்லா இந்திரியங்களிலும் செயல்களைச் செய்கிறார்கள். சேவகர்களின் சேவைக்கேற்ப பலன் தரும் அரசனைப்போல், ஹரி தன் இயற்கையான சுதந்திரத்தைப் பிரித்து அளித்தான்.",
        '0.4': "(எண்கள் ஓரளவு தெளிவற்றவை.) எண்ணற்ற சுதந்திரத்தை நான்கு பங்காகப் பிரித்து ஒன்றை எடுத்துப் பத்து வகை செய்து, ஐந்து பிராணன்களுடைய வாயுவுக்கும் நான்முகனுக்கும் பங்குகள் அளித்து (பிரம்மாவிடம் ஐந்தேகால் பங்கு), மீண்டும் பத்து வகை செய்து இரண்டை ஸதாசிவனிடம் வைத்தான்.",
        '0.5': "(எண்கள் ஓரளவு தெளிவற்றவை.) இந்திரன், காமனிடம் ஒன்றரை, பத்து இந்திரியங்களின் தேவர்களிடம் ஒன்று, மற்ற எல்லா ஜீவர்களிடம் ஒன்று, கலி முதலிய தைத்திய கூட்டத்துக்கு நாலரை பங்குகள் அளித்தான். லக்ஷ்மி மற்றும் தன் பங்கு பற்றிய கடைசி வரிகள் தெளிவற்றவை.",
        '0.6': "தேவர், மனிதர், அசுரர்களிடையே தத்துவங்களைப் பகுத்து வைத்து ரமாவிநோதியான ஹரி அந்த மூன்று வகையினருக்குள்ளும் இருந்து விளையாடுகிறான். அவர்களின் கர்மத்தை மாற்றாமல் கல்பத்தின் முடிவில் ஒவ்வொருவருக்கும் அவரவர் கதியை சிரமமின்றி அளிக்கிறான்.",
        '0.7': "வீடுகளில் உள்ள விளக்கின் சுடர் திரிகளைப் பின்பற்றி மக்கள் கூட்டத்துக்குப் பொருந்துவதுபோல், ஹரி எங்கும் அவரவருக்கேற்றபடி தோன்றுகிறான். காலந்தோறும் ஸ்ரீ, பூ, துர்கையருடன் சுகமயமான லீலை செய்யும்போது ஜீவர்களுக்கு முக்குணச் செயல்கள் நிகழ்கின்றன.",
        '0.8': "இந்திரியங்களால் செய்யும் கர்ம இணைகளை (புண்ணிய பாவங்களை) தனக்கு அர்ப்பணித்தால் கோவிந்தன் புண்ணியத்தை ஏற்று பாவத்தை எரித்துவிடுகிறான். இந்திரேசன் பக்தர்களை நிந்திப்பவர்களிடம் உள்ள புண்ணியத்தை எடுத்து தன்னவர்களுக்கு அளிக்கிறான், அந்த நிந்தகர்களுக்கு பாவங்களை ஊட்டுகிறான்.",
        '0.9': "(இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.) உரிய நேரத்தில் பாவச் செயல்களுக்குத் தூண்டுபவர்களை நிந்திக்காமல், தன்னினும் உயர்ந்தவர்களின் குணகர்மங்களைப் புகழாமல் இருக்கும் மனிதர்களுக்கு பசு, பிராமணன், பெண் கொலை முதலிய எல்லாக் குற்றங்களையும் அவன் அளிக்கிறான். இதில் சந்தேகப்படாதே; இது எல்லா சாஸ்திரங்களின் கருத்து.",
        '0.10': "தன் சுதந்திரத்தின் பகுதிகளை ஹிரண்யகர்ப்பன் முதலியோருக்கும் கலி முதலிய அசுர வம்சத்துக்கும் அவரவர் அதிகாரத்துக்கேற்ப அளித்து புண்ணிய பாவங்களைத் தரும் கருணைக்கடல், குறைந்த ஆற்றலுடையவர்கள் தாமாக அனுபவிக்கத் தெரியாததால் எல்லோரையும் அனுபவிக்கச் செய்தான்.",
        '0.11': "சத்யவிக்ரமனான ஹரி எல்லோருக்கும் புண்ணிய பாவங்களை அளிப்பதற்காக நாற்பது பங்குகளாக்கி மக்களுக்கு லேசான பங்கை அளிக்கிறான். ஆற்றலைத் தானே அளித்து எப்போதும் பருப்பொருள்களைத் தான் அனுபவித்து எல்லா ஜீவர்களையும் அனுபவிக்கச் செய்கிறான்.",
        '0.12': "இருளும் சூரியனும் எப்போதாவது ஓரிடத்தில் இருக்குமா? மலைக்கு அலைச்சல், குளிர், வெயில் அச்சம் உண்டா? அதுபோல் லக்ஷ்மீரமணன் எண்ணற்ற ஜீவர்களுக்குள் இருந்து செயல்களைச் செய்தும் ஏரியிலுள்ள தாமரை இலைபோல் ஒட்டாமல் இருக்கிறான்.",
        '0.13': "பிரம்மா முதலிய தேவர்களுக்கும் கலி, சம்பரன் முதலிய எல்லா தைத்தியர்களுக்கும் நாள்தோறும் புண்ணிய பாவங்களைப் பகிர்ந்து, கடல்நீரை பெரிய குடத்தின் கொள்ளளவு அறிந்து நிரப்புவதுபோல், அவர்களின் பிரதிபிம்பங்களுக்குள் (பிம்பமாக) தான் இருந்து அவர்களின் தகுதிக்கேற்ற பலனை அளிக்கிறான்.",
        '0.14': "இவ்வளவும் விஷ்ணுரஹஸ்யத்தில் பிருகு முனிவர் இந்திரத்யும்னனுக்குக் கூறியது; அறிஞர்கள் பொறாமையை விட்டு இதை நாளும் கேட்க வேண்டும். தகாத சொற்கள் இருந்தாலும் கணக்கில் கொள்ள வேண்டாம் என்று வித்வான்களிடம் பணிவுடன் வேண்டுகிறேன்.",
        '0.15': "அச்சமற்றவன், விஸ்வேசன், பிரம்மாவின் தந்தை, மாமனைக் கொன்றவன், மத்வப்ரியன், பூதபாவனன், எண்ணற்ற சூரியர்களின் ஒளியுடையவன், மகாராஜன், கௌதமரின் மனைவியைக் காத்தவன், அநாதரக்ஷகன், குருக்களில் சிறந்தவன் ஆன ஜகந்நாத விட்டலன் தன்னை நம்பிய பக்தர்களைக் காக்கிறான்.",
      },
    },
    'harikathamrutasara-18': {
      summary: "பதினெட்டாம் ஸந்தி (க்ரீடாவிலாஸம், ஸர்வஸ்வாதந்த்ரியம்): செரிமானம் முதல் பேச்சு, உறக்கம் வரை ஜீவர்களின் எல்லாச் செயல்களையும் ஹரி தன் லீலைக்காகவும் அவரவருக்குக் கதி அளிப்பதற்காகவும் அவர்களுக்குள் இருந்து செய்கிறான். தன் சுதந்திரத்தை குறிப்பிட்ட பங்குகளாகப் பகிர்ந்தான் (நூறில் பிரம்மாவுக்கு 52, வாயுவுக்கு 48; மற்றொரு நூறில் சிவனுக்கு 20, இந்திரன்-காமனுக்கு 15, தேவர்களுக்கு 10, ஜீவர்களுக்கு 10, தைத்தியர்களுக்கு 45). செயல்களை அர்ப்பணித்தவர்களின் புண்ணியத்தை ஏற்று பாவத்தை எரிக்கிறான்; அர்ப்பணிக்காதவர்களின் புண்ணியத்தை உரிமையாளர் இல்லாத மரத்தின் பழம்போல் தைத்தியர்கள் கொண்டுசெல்கின்றனர். நாவில் ஒரு ஹரிநாமம் இருந்தாலும் அவனது காப்பு கிடைக்கிறது; பாகவத சிரவணம், எல்லா இந்திரியங்களையும் வாயுவுக்கு அர்ப்பணித்தல் என்ற அறிவுரையுடன் ஸந்தி முடிகிறது.",
      verses: {
        '0.0': "குருவின் கருணையால் ஹரிகதாம்ருதஸாரத்தைச் சொல்கிறேன்; பரம பகவத்பக்தர்கள் இதை ஆதரவுடன் கேட்க வேண்டும்.",
        '0.1': "செரித்தல், உண்ணுதல், நடத்தல், உணவு, பேச்சு, மைதுனம், உறக்கம், பார்த்தல், அசையாதிருத்தல், அசைதல் ஆகிய முயற்சிகள் மக்களுக்கு (அவனின்றி) சாத்தியமா? தூய இல்லத்தவனான ஹரி கருணையால் ஜீவர் கூட்டத்துக்குள் இருந்து இந்தத் தகுந்த தகாத செயல்களைத் தானே செய்கிறான் என்று அறிந்து அவனைப் புகழ்.",
        '0.2': "விஸ்தரச்ரவனான ஹரி உடலுக்குள் புகுந்து இடைவிடாது பல செயல்களைச் செய்யும்போது அதைக் கண்டு மக்கள் 'இவன் உயிருடன் இருக்கிறான்' என்கிறார்கள்; அதைக் கண்டு தாழ்ந்தவர்கள் எல்லோரும் மகிழ்ந்து பணிவிடை செய்கிறார்கள்; அவன் விட்டுப்போன கணத்தில் அது பிணம் என்று அறிந்து புறக்கணிக்கிறார்கள்.",
        '0.3': "தன் லீலைக்காகவும் அவரவருக்குக் கதி அளிப்பதற்காகவும் உடல்களைத் தந்து, பிரம்மா, சிவன் முதலியோருக்குள் புகுந்து தன் விருப்பப்படி விளையாடுகிறான்; மூட தைத்தியர்களுக்குள் இருந்தும் நாள்தோறும் பலவகைச் செயல்களைச் செய்கிறான். இதனால் அவனுக்கு இழப்பும் இல்லை, ஆதாயமும் இல்லை; இதை எக்காலத்திலும் அறி.",
        '0.4': "க்ஷரர்களால் துதிக்கப்படும் ஹரி பிரம்மா, வாயு, சிவன், இந்திரன், தேவர் அசுரர் எல்லோருக்குள்ளும் அத்யக்ஷனாக இருந்து எல்லோரிடமும் செயல்படுகிறான். அழிவற்றவன், சத்தியாத்மா, பிறர் உதவியை நாடாதவன், எல்லோரினும் வேறுபட்டவன் ஆகி உலகைக் காக்கிறான்.",
        '0.5': "ஸ்ரீ, சரஸ்வதி, பாரதி, கிரிஜை, சசி, ரதி, ரோஹிணி, ஸஞ்ஜ்ஞை, சதரூபை முதலிய எல்லாப் பெண்களுக்குள்ளும் பெண் வடிவில் நிலைத்து, எல்லோருக்கும் தன்னிடம் நம்பிக்கையை அளித்து, அவர்களின் தகுதிகளை அறிந்து அவர்களின் விருப்பங்களை நிறைவேற்றுகிறான்.",
        '0.6': "குச்சியைக் குதிரையாக்கி விளையாடும் சிறுவர்களைப்போல், லக்ஷ்மிலோலன் சுதந்திர குணத்தை பிரம்மா முதலியோரிடம் வைத்து லீலை செய்கிறான்; தன்னவர்களுக்கு எப்போதும் சாதகமாகவும் தீயவர்களுக்குப் பாதகமாகவும் தன்னை வெளிப்படுத்தாமல் இருக்கிறான்.",
        '0.7': "கருடவாகனன் ஹரி பல உருவம் பெயர்களால் அழைக்கப்பட்டு அவர்களின் அருகில் இருந்து எல்லாச் செயல்களையும் செய்கிறான்; அவர்களின் இயல்புகளுக்கேற்ப பாவம் புண்ணியம் இரண்டையும் ஊட்டுகிறான்; அவன் பரோபகாரி, பரமேசன், பூர்ணானந்த ஞானகனன்.",
        '0.8': "(சம்சாரத்தில்) உழல்பவன் லக்ஷ்மிமஹிதனின் பெரும் மகிமைகளை எப்படி அறிவான்? நாளும் உலக இன்பத்தை மறந்து, மனதில் ஏற்று, சாஸ்திரப் பொருளை பேரார்வத்துடன் புகழ்ந்து தன்னை மறந்தவர்களுக்கன்றி மற்றவர்களுக்கு அவை தெரியாது.",
        '0.9': "பந்தம், மோக்ஷம் தருபவனைப் பற்றிய ஞானம் மந்தமதியினருக்கு எப்படிக் கிடைக்கும்? துளி அளவு சுகத்துக்கு மலையளவு துன்பம் உண்டு என்று அறியாமல் பிற தெய்வங்களிடம் சுகத்தை எதிர்பார்க்கிறார்கள். முகுந்தனின் ஆராதனையை விட்டவனுக்கு முக்தி சுகம் உண்டா?",
        '0.10': "(பாடலின் முடிவு முழுமையற்றது.) அரசன் தன் அமைச்சர்களுக்குக் கருணையுடன் அதிகாரம் அளித்து, தன் மக்களுக்குப் பணிகளை ஒப்படைத்து மானம் அவமானம் செய்வதுபோல், ஸ்ரீஜனார்த்தனன் எல்லோருக்குள்ளும் வெல்லப்படாதவனாக இருந்து எல்லாப் பயன்களையும் செய்தும் செய்வித்தும் பலனுக்கு ஆளாக்குகிறான்.",
        '0.11': "வாசுதேவன் தன் சுதந்திரத்தை பிரம்மா முதலிய தேவ அசுரர்களுக்கு அளிப்பதற்காக பாதியை எடுத்து, அதில் பாதியை நான்கு பங்காக்கி, ஒன்றை நூறு வகை செய்து, பிரம்மாவுக்கு ஐம்பத்திரண்டு, வாயுவுக்கு நாற்பத்தெட்டு அளித்தான்; வாணி, பாரதியருக்கு அதில் பாதி.",
        '0.12': "மற்றொரு பகுதியை எடுத்து நூறு பிரிவுகளாக்கி, இருபதை சிவனிடம், பதினைந்தை இந்திரன் காமனிடம், பத்தை எல்லா தேவர்களிடம், பத்தை ஜீவ கூட்டத்திடம், நாற்பத்தைந்தை தைத்தியர்களிடம் வைத்தான்.",
        '0.13': "(பாடலின் முடிவு முழுமையற்றது.) மீதியை மூன்றாகப் பிரித்து இரண்டைத் தன்னிடம் வைத்து ஒன்றை லக்ஷ்மிக்கு அளித்தான். எல்லோருக்கும் சுதந்திரம் அளித்து, அரசன் தன் பின்பற்றுபவர்களுக்குப் பணி அளித்து நல்லது தீயதை ஆராய்வதுபோல், முக்குணங்களை வெளிப்படுத்துகிறான்.",
        '0.14': "புண்ணியச் செயலுக்கு உதவும் பாக்கியசாலிகளுக்கு கலி முதலிய தைத்தியர்களின் புண்ணிய பலன்களை அளிக்கிறான்; தேவர்களின் பாவச்செயலின் பலனை பிற செயல் செய்பவர்களுக்கு ஏற்றபடி அளிக்கிறான்; இப்படிப்பட்ட கருணைக்கடலான ஒப்பற்றவனுக்கு நிகரானவன் உண்டா?",
        '0.15': "(இப்பாடல் அடுத்த பாடலில் தொடர்கிறது.) 'ஒப்பற்றவனுக்கும் நிகர் உண்டு' என்று சொல்பவன், அவனது பக்தர்களிடம் பொறாமை கொள்பவன், குணத்துக்கும் குணமுடையவனுக்கும் பேதம் கூறுபவன், சங்கு சக்கரம் ஊர்த்வபுண்டரம் தரித்தவர்களிடம் வெறுப்பவன், ஹரியின் சரிதங்களைக் கேளாமல் உலகியல் செய்திகளைக் கேட்பவன்...",
        '0.16': "(பாடலின் முடிவு முழுமையற்றது.) ...வெறுப்புடைய இத்தகைய தீய ஜீவர்கள் அனைவரையும் ஞானிகள் தைத்தியர்கள் என்பர். அறிஞர்களின் ஞானத்தையும் செயல்களையும் கண்டு நிந்திக்கிறார்கள்; தேவதேவனை விட்டு வாழ்நாள் முழுவதும் அற்பர்களுக்குச் சேவை செய்து பிழைக்கிறார்கள், அறியாமைக்கு உட்பட்டு.",
        '0.17': "(இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.) காமம், பேராசை, கோபம், செருக்கு, வன்முறை, மாயை, பொய், ஆடம்பரம், கபடம்; த்ரிதாமனின் அவதாரங்களில் பேதம் காண்பது; இறைச்சி நிவேதனம் போன்ற மிகத் தாமஸ உணவை உண்பது; தாமஸரும் செல்வச் செருக்கால் குருடானவர்களுமானவர்களின் சேர்க்கையால் இருளே வளர்கிறது.",
        '0.18': "நல்லோரின் குணங்கள்: ஞானம், பக்தி, வைராக்கியம், பணிவு, புராண சாஸ்திர சிரவணம், சிந்தனை, தானம், சமம், தமம், யஜ்ஞம், சத்தியம், அஹிம்சை, உயிர்களிடம் இரக்கம், தியானம், பகவன்நாம கீர்த்தனம், மௌனம், ஜபம், தவம், விரதம், தீர்த்த ஸ்நானம், மந்திரம், ஸ்தோத்திரம், வந்தனம்.",
        '0.19': "சிறிய சுதந்திர குணத்தை அவர்களிடம் புகுத்தியதால் சத்வ அசத்வ ஜீவர்களிடம் குண தோஷங்கள் தோன்றுகின்றன. மூச்சு, உணவு, பானம், உறக்கம், விளையாட்டு, மைதுனம், நடை, மகிழ்ச்சி, துன்பம், கனவு, ஆழ்ந்த உறக்கம், விழிப்பு ஆகியவை உயிருள்ளவனுக்கு ஏற்படுகின்றன.",
        '0.20': "(இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.) பாதியைத் தன்னிடம் வைத்து மீதிப் பாதியைப் பிரித்து, வ்ருஜினார்த்தனன் முன்பு போலவே சுதந்திரம் அளித்தான்; கங்கையின் தந்தை, கொடுப்பவர்களின் சுக வளர்ச்சிக்காக, பிரம்மா, வாயு, சிவன் முதலியோருக்குள் இருப்பவர்களின் தகுதியை அறிந்து...",
        '0.21': "ஹலதரானுஜன் செய்யும் செயலை அறியாமல் அகங்காரத்தால் 'நானன்றி விதி நிஷேதத்துக்குரியவர் யாரும் இல்லை' என்பவனுக்கு இரண்டு பலன்களையும் அளிக்கிறான்; தைத்தியர்களின் மாசடைந்த செயல்களை விட்டு அவர்களின் புண்ணியத்தை இழுத்துத் தன்னுள் வைத்து முறையாக பக்தர்களுக்கு அளிக்கிறான்.",
        '0.22': "சூரியக் கிரணங்களைப் பின்பற்றி மரத்தின் நிழல் இருப்பதுபோல், தாமரைக்கண்ணனான ஹரி எல்லோருக்குள்ளும் வியாபித்திருப்பதால் தீய, நல்ல குணச் செயல்கள் தோன்றுகின்றன. நியாயம் அறிந்தவர்களுக்கு 'ஸ்ரீயரசனே உத்தமர்களில் உத்தமன்' என்று இடைவிடாது சொல்கிறார்கள்.",
        '0.23': "மூலகாரணப் பிரகிருதி எனப்படும் மஹாலக்ஷ்மி எல்லோருக்குள்ளும் இருந்து லீலை செய்கிறாள்; புண்ணிய பாவங்களை அவளது கணவனுக்கு அர்ப்பணித்தால், பாற்கடலில் விழுந்த நீர் வெறும் நீர் எனப்படாதது போல், ஜீவர்கள் செய்த செயல்கள் எப்போதும் சுபம் எனப்படுகின்றன.",
        '0.24': "ஞானம், சுகம், பலம் நிறைந்த விஷ்ணுவை முக்குணச் செயல்கள் என்ன செய்யும்? உலகில் புழு நெருப்பைத் தின்னுமா? பிரம்மா, சிவன், தேவ அசுரர்களுடன் இந்த அண்டத்தை காலாக்னியில் விழுங்குபவனுக்கு இந்தப் பாவங்களின் அச்சம் உண்டா?",
        '0.25': "(இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.) தைத்திரீயம் முதலிய ஸ்ருதிகள் 'மோதம் வலப்புறச் சிறகு, ப்ரமோதம் வடக்குப் (இடப்) புறச் சிறகு' என்கின்றன. ஆனந்தமயனான ஹரி இவ்வுலகின் சிறப்பு சுகத்தையும் (மோதம்) மறுவுலக சுகத்தையும் (ப்ரமோதம்) அளிப்பதால் மோதன், ப்ரமோதன் எனப்படுகிறான்.",
        '0.26': "மழையால், பூமியிலுள்ள எல்லா நீராலும் கடல் எப்போதாவது பெருகுமா? மழை வராவிட்டால் வறண்டுபோகுமா? குறையற்ற, சுயானந்த நிறைவுடைய இயல்புடையவனிடம் கர்மம், அகர்மத்தால் பிறக்கும் பலன்கள் வந்து என்ன செய்யும்?",
        '0.27': "உடல் என்னும் மரத்தில் எப்போதும் பிரியாமல் பேரன்புடன் இரண்டு பறவைகள் உள்ளன: கர்மப் பலன்களை உண்ணும் ஜீவப்பறவையும், சாரத்தை அனுபவிக்கும் ஸ்ரீஹரியும். துரோகிகளான கலி முதலிய தைத்திய கூட்டத்துக்கு அவர்களின் சிறப்புப் பாவத்தையும், எல்லோருக்கும் சிறிதளவு பாவத்தையும் அளிக்கிறான்.",
        '0.28': "சூரியக் கிரணத்தைக் கண்டதும் இருள் ஓடுவதுபோல், லக்ஷ்மிரமணன் பார்த்த மாத்திரத்தில் பாவம் அழிகிறது. பிரம்மா முதலிய எல்லா தேவர்களிடமும் உள்ள பாவக்குவியலை தேவர்களின் வாயான அக்னியைப்போல் ஹரியே சாம்பலாக்குகிறான்.",
        '0.29': "(இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.) நானூறு பங்குகளில் பத்தாவது பகுதியிலிருந்து மற்ற ஜீவர்களுக்கு சிறிதளவு அளிக்கிறான்; தைத்தியர்களுக்கும் தேவர்களுக்கும் சிறப்பு துன்ப இன்பங்களை அளிக்கிறான்; அறிவற்ற உயிர்களுக்கு அவற்றின் தகுதி அறிந்து எறும்பு, கொசு முதலியவற்றுக்கு ஆஹுதியின் சுகத்தையும் மரணத்தின் துன்பத்தையும் அளிக்கிறான்.",
        '0.30': "(இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.) கலி தன் பணியாட்களுடன் அந்தந்தமஸ் என்னும் நித்திய நரகக் குழியை அடைகிறான். ஹரியின் திருவடித்தாமரைகளை பக்தியுடன் வழிபட்ட ஸத்யலோகாதிபதி நான்முகப் பிரம்மா தத்துவ தேவர்களுடன் மீளாத தன் முக்தி உலகை அடைகிறான்.",
        '0.31': "விதி, நிஷேதம் இரண்டையும் மறக்காமல் மதுவிரோதியின் திருவடிகளில் அர்ப்பணித்தால் அவன் புண்ணியத்தை அதிதியின் மக்களுக்கும் பாவத்தை தைத்தியர்களுக்கும் அளிக்கிறான். சுதர்சனதரனுக்கு அளிக்காவிட்டால் தைத்தியர்கள் வந்து உரிமையாளர் இல்லாத மரங்களின் பழம்போல் புண்ணியத்தை எப்போதும் கொண்டுசெல்கிறார்கள்.",
        '0.32': "விளக்கு எள் எண்ணெயின் வண்டலை விட்டு தெளிந்த எண்ணெயை ஏற்று வீட்டில் நிறைந்த இருளை அகற்றுவதுபோல், ஹரி கலி முதலிய எல்லா தானவ குலத்தோர் நாளும் செய்யும் புண்ணியத்தின் பலனை பிரம்மா முதலியோருக்கு அளித்து அவர்களுக்குள்ளேயே விளையாடுகிறான்.",
        '0.33': "(பாடல் வாக்கியத்தின் நடுவிலிருந்து தொடங்குகிறது.) நாளும் தூய, தூய்மையற்ற பொருள்களை உண்டாலும் உலகிலும் வேத ஸ்மிருதிகளிலும் தூயவன் என்று அழைக்கப்படுகிறான்; அறிஞர்கள் அறிந்தே நம்பிக்கையுடன் அர்ப்பணித்த செயல் விலக்கப்பட்டதாயினும் ஏற்று உயர்த்துகிறான்.",
        '0.34': "(பாடலின் முடிவு தெளிவற்றது.) உரிமையாளர் உள்ள காட்டுப் பழங்களை அடித்து உண்பவர்கள் உண்டா? பார்த்தால் அடித்து எறிவார்கள் என்ற பயத்தால் பார்க்கவும் அஞ்சுகிறார்கள். அதுபோல் இடைவிடாமல் செய்யும் செயல்கள், வீடு, மனைவி, பிள்ளைகள், உறவினர்கள்...",
        '0.35': "ஞானேந்திரியங்கள், கர்மேந்திரியங்களால் செய்யும் எல்லாச் செயல்களையும் காலந்தோறும் லக்ஷ்மிநிவாஸனுக்கு அர்ப்பணித்துக்கொண்டிரு. பிராணபதி அவற்றை ஏற்றால் மீண்டும் பல பிறவிகளைத் தருவதில்லை; அளிக்காவிட்டால் தானவர்கள் எல்லாப் புண்ணியக் குவியல்களையும் இழுத்துச் செல்கிறார்கள்.",
        '0.36': "ஸ்ருதி ஸ்ம்ருதிகளின் பொருளை அறிந்தும் 'நான் செய்கிறேன்' என்ற அகங்கார எண்ணம் உடையவன் செயல் செய்தால் ஹரி அதை ஏற்பதில்லை, மாறாக பாவங்களை அளிக்கிறான். 'ஹரி பதினான்கு உலகங்களின் அதிபதி, யஜ்ஞங்களுக்கு நன்றியுள்ள நியாமகன்' என்பவனுக்கு புத்திக்கோளாறு, தவறு, துன்பம் ஆகிய குற்றங்கள் இல்லை.",
        '0.37': "(பாடல் முடிவுறாமல் நிற்கிறது.) பிரம்மா முதலிய முக்கியர்கள் அவனது ஆணையைச் சுமப்பவர்கள் மட்டுமே. ரமாரமணனே முழு சுதந்திரன் என்று அறிந்து, விரும்பிய விரும்பாத செயல்களின் பலன்களை சாரத்தை அனுபவிப்பவனுக்கு அர்ப்பணித்தால் அவன் ஏற்கிறான்; பாவத்தின் பலனை குபேரன் என்ற தைத்தியர்களுக்கு அளித்து...",
        '0.38': "(ஒரு தொடர் தெளிவற்றது.) கொடிய தைத்தியர்களுக்குள் இருந்து தானே அவர்களைத் தூண்டுவதால் ஹரியை குபேரன் என்கிறார்கள். அறிஞர்களால் அடையத்தக்கவன் என்பதால் சூரியன் என்கிறார்கள்; துயரத்திலிருந்து தொலைவில் இருப்பதால் சுக்லன்; லிங்க சரீரம் இல்லாததால் அகாயன் எனப்படுகிறான்.",
        '0.39': "சொல்ல இயலாத பெரும் பாவக்குவியல்களை ஒரே கணத்தில் வேரோடு அழிக்க வேண்டும் என்பவனுக்கு, நாவில் ஒரு ஹரிநாமம் இருந்தாலும், பரமகருணையுள்ள கிருஷ்ணன் கைபிடித்து தன் இல்லத்தில் வைத்து நாள்தோறும் மகிழ்விக்கிறான்.",
        '0.40': "நோயாளி மருந்தாலும் பத்தியத்தாலும் நோயற்றவனாவதுபோல், ஸ்ரீமத் பாகவதத்தை நன்கு கேட்டு பவம் என்னும் நோயை நீக்கி, சப்தம் முதலிய எல்லா விஷயங்களையும் பத்து இந்திரியங்களையும் வாயுவுக்கு அர்ப்பணி. அப்போது ஸ்ரீகுரு ஜகந்நாத விட்டலன் மகிழ்வான்.",
      },
    },
    'harikathamrutasara-19': {
      summary: "பத்தொன்பதாம் ஸந்தி (கர்மவிமோசனம், கர்மபந்தத்திலிருந்து விடுதலை): மூல நாராயணன் எல்லாவற்றிலும் காரணனாகவும் அந்தராத்மாவாகவும் இருந்து, தன் வடிவங்களில் லீலை செய்து, எல்லாச் செயல்களையும் அவற்றின் பலனுபவத்தையும் தானே செய்தும் செய்வித்தும் வருகிறான், ஆயினும் ஒட்டாமல் இருக்கிறான். இதை அறிந்து பற்றின்றி எல்லாச் செயல்களையும் ஹரிக்கு அர்ப்பணிப்பவனை புண்ணிய பாவங்கள் பற்றுவதில்லை; ஹரி அவன் குற்றங்களை எண்ணாமல் காக்கிறான். பக்தியற்ற சடங்கு, நூல்படிப்பு, தவம் ஆகியவை தவளை மீது ஏறிக் கடல் கடப்பதுபோல் பயனற்றவை; ஹரியிடம் சிறு சுகத்தை அல்ல, பக்தியையே கேட்க வேண்டும். அவன் ஞானிகளுக்கு அருகில், தீயவர்களுக்கு தொலைவில்; கன்றின் அழைப்புக்கு பசு வருவதுபோல் பக்தனின் அழைப்புக்கு வருகிறான், சபரியின் பழத்தையும் சுதாமனின் காணிக்கையையும் ஏற்றதுபோல்.",
      verses: {
        '0.0': "குருவின் கருணையால் ஹரிகதாம்ருதஸாரத்தைச் சொல்கிறேன்; பரம பகவத்பக்தர்கள் இதை ஆதரவுடன் கேட்க வேண்டும்.",
        '0.1': "(இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.) மூல நாராயணன் மாயாலோலனாக எண்ணற்ற அவதாரங்களில் லீலை செய்கிறான்; ஜயாரமணன் ஆவேச வடிவிலும் இருக்கிறான்; எண்ணற்ற உயிர்த்திரளில் ப்ரத்யும்னனாகவும், அண்டமாகிய ஆலயத்தின் உள்ளும் புறமும் சாந்திபதி அநிருத்தனாகவும் நிலைத்திருக்கிறான்.",
        '0.2': "ஐந்து காரண வடிவங்களும் இருபத்தைந்து காரியம் எனப்படும் வடிவங்களும், இவ்வாறு முப்பது வடிவங்களில் அவன் இந்தச் சராசரத்தில் இன்புறுகிறான்; தான் பேதமற்றவன். மூவுலகங்களின் பிறப்பு முதலியவற்றுக்குக் காரணனும் முக்தி அளிப்பவனுமான சர்வஞ்ஞன் எல்லோரையும் தன் வயிற்றில் வைத்துத் தேற்றுகிறான்.",
        '0.3': "(இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.) காரியம், காரணம், கர்த்தாக்கள் ஆகியோருக்குள் தன் மனைவியருடன் கபிலாசாரியன் விளையாடுகிறான்; அவனைத் தூண்டுபவர் யாரும் இல்லை. தன் வீரத்தால் தேவர்களைக் காத்து தானவர் கூட்டத்தை நாள்தோறும் தண்டிக்கிறான்; ரமா, பிரம்மா, சிவன் ஆகியோர் மதிக்கின்றனர்.",
        '0.4': "வியாபித்தவனும் ஆவேசனுமான ஹரி இந்த அனைத்து உலகிலும் ஆகாயத்திலும் இருந்து அவதாரங்களின் அந்தராத்மாவான பரமாத்மா. அழிவற்றவன் உலகினுள் அவகாசம் (ஆகாயம்) ஆகி, யோகீசர்களின் இதய ஆகாயத்தில் நிலைத்து, எல்லோரையும் தன்னுள் வைத்துக் காக்கிறான்.",
        '0.5': "விறகிலும் கல்லிலும் உள்ள நெருப்பு தனித்தனியாக இருப்பதுபோல், காரண காரியங்களுக்குள் இருந்து காரணன், காரியன் என்று அழைக்கப்பட்டு, வெளிப்படாமல் எல்லோரிடமும் செயல்பட்டு, அவரவர் தகுதிக்கேற்ற சாரப் பலன்களை ஊட்டித் தேற்றுகிறான் கருணைக்கடல்.",
        '0.6': "அலைகளைப்போல் எழும் கர்ம, விகர்மங்களால் பிறக்கும் நல்ல தீய பலன்களை நிர்மலாத்மா செய்தும் செய்வித்தும் ஊட்டுகிறான்; பற்றற்றவன், நோயற்றவன், ஆதாரம் தேவையற்றவன், தர்மம் அறிந்தவன், தர்மாத்மா ஆன அவனை தீய மதியுடையவர்கள் விரும்புவதில்லை; ஒப்பற்ற மல்லன் ஸ்ரீநாயகன்.",
        '0.7': "கடலின் வடவாக்கினிகள் கடல்நீரைக் குடிக்கின்றன, மேகம் மழை பொழிந்து பூமிக்கு அமைதியளிக்கிறது, நெருப்பு தானே உண்கிறது. அவ்வாறே லக்ஷ்மிநிலயன் சர்வவியாபி குணங்களால் செய்த செயல்களின் நல்ல தீய பலன்களைத் தானும் உண்டு எல்லா ஜீவர்களுக்கும் ஊட்டுகிறான் என்று அறி.",
        '0.8': "நூல்களைப் பார்த்து மந்திர துதிகளைச் சொல்வதால் என்ன பலன்? சூரியோதயம் முதல் அஸ்தமனம் வரை ஜபம் தவம் செய்து என்ன பயன்? இதயத்திலுள்ள பரமாத்மாவே எல்லா நிலைகளிலும் இருந்து, பற்றின்றி எல்லோரிடமும் செய்தும் செய்வித்தும் வருகிறான் என்பதை அறியாதவனுக்கு?",
        '0.9': "மதுக்குடத்தை தேவநதியில் அமிழ்த்தி நாளும் கழுவினாலும் அது எப்போதாவது தூய்மையாகுமா? அவ்வாறே ஹரியின் திருவடித்தாமரைகளை அறிவுடன் வழிபடாத அதம ஜீவர்களுக்கு சாதகமாகத் தோன்றும் எல்லாச் செயல்களும் அவற்றின் செழிப்புகளும் துன்பத்தையே தருகின்றன.",
        '0.10': "பக்தியுடன் முக்தர், அமுக்தர் ஆகியோரின் நியாமகனுடைய மிகுந்த மகிமைகளை மறவாமல் இடைவிடாது புகழ். உலகியல் செய்திகள், ஈடுபாடுகளில் பற்றுக்கொள்ளாமல் அவற்றை விட்டு, இது ஹரியின் ஆணை என்று அறிந்து ஸ்ருதி ஸ்ம்ருதிகள் கூறிய செயல்களைச் செய்துகொண்டிரு.",
        '0.11': "செயலில் குறை ஏற்பட்டாலும், நீ பற்றின்றிச் செய்தால் கர்மத்தால் பிறக்கும் பாவ புண்ணியங்கள் இரண்டும் உன்னைப் பற்றா. கருடவாகனன் உன் பெரும் குற்றங்களை எண்ணாமல் சொர்க்கம், மோக்ஷம் அளித்துக் காக்கிறான்; அவன் எப்போதும் சுகம் நிறைந்தவன்.",
        '0.12': "ஸ்வரதன், சுகமயன், எளியவன், விஸ்வம்பரன், துயரற்றவன், சுரர் அசுரரால் வணங்கப்படும் திருவடியிணை உடையவன், அழகிய உறுப்புகளுடையவன், சார்ங்கதாரி, சரண்யன், கோபத்தை வென்றவன், மிக அழகியவன், பரத்தினும் பரன், சரணடைந்தவர்களின் காமதேனு, நித்தியன், கருணையுள்ளவன், தாமரைக்கண்ணன் — 'காப்பாற்று' என்று அழைத்தால் நித்தியசித்தனான அவன் விளங்குகிறான்.",
        '0.13': "நீ தூயவனாகி, செயல்களையும் விகர்மங்களையும் இடைவிடாது ஸுதர்மன் என்ற பெயருடையவனுக்கு அர்ப்பணித்து களங்கமற்றவனாகு. ஹிரண்யகர்ப்பனின் தந்தை கருணையால் உன்னைத் தீய மதியினருக்குக் கொடுக்காமல் தன் மாளிகையில் வைத்து எல்லாக் காலத்திலும் கிருபையுடன் காக்கிறான்.",
        '0.14': "ஒவ்வொரு கல்பத்திலும் சரணடைந்தோரின் கற்பகமரம் தன் சங்கல்பப்படி விரும்பிய விரும்பாத பலன்களை அளிக்கிறான். சிறு சுகத்தை விரும்பி பாம்புப் படுக்கைக்காரனை எப்போதும் வழிபடாதே; சிற்பியின் கையில் சிக்கிய கல்லைப்போல் உன்னை வடிவமைத்துத் தேற்றுகிறான்.",
        '0.15': "இடவேறுபாட்டால் வேறுபட்டுத் தோன்றும் ஆகாயத்தைப்போல் வாசுதேவன் எல்லா உயிர்களிலும் உறைந்து சராசரங்களின் ஆத்மா என்று அழைக்கப்படுகிறான். உடல்களில் இருந்தாலும் அவனுக்கு வெறுப்பு, நட்பு, அலட்சியம் இல்லை; பரப்பிரம்மன் அவரவர் உபாசனைக்கேற்ப பலனளிக்கிறான்.",
        '0.16': "(இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.) பிரம்மாவின் தந்தையை வழிபட்டால் துன்பங்கள் மின்னலைப்போல் நிலைக்காமல் படிப்படியாக அழிகின்றன. வஞ்சிப்பவர்களை அவன் விரும்புவதில்லை; ஸ்ரீவத்ஸ மார்புடையவன், ஏழைகளுக்குப் பிரியமானவன் ஆன புருஷேசன் இதய ஆகாயத்தில் மின்னல்போல் ஒளிர்கிறான்.",
        '0.17': "காலம், பொருள், நற்செயல்களின் தூய்மை எல்லாப் பாவங்களையும் எப்போதும் வேரறுக்கும் என்று அற்பருக்குக் கூறுகிறார்கள்; அறிவிலிகள் எண்ணெய்த் தாரையைப்போல் இடைவிடாது அவன் திருவடிகளைப் பணிந்து துதிக்காமல், கர்மம் முதலியவையே கரைசேர்ப்பவை என்கிறார்கள்.",
        '0.18': "பிரம்மா, சிவன், இந்திரன் முதலிய எல்லா தேவர்களும் இவனது கடக்க முடியாத மகிமைகளின் முடிவை மனத்தாலும் சொல்லாலும் காணாமல் களைத்து, திருவடித்தாமரை என்னும் கற்பகமரத்தின் நிழலை அடைந்து 'லக்ஷ்மீரமணா, தேற்று' என்று மிகுந்த பக்தியுடன் வேண்டுகிறார்கள்.",
        '0.19': "(கவியின் கருத்து.) நீர்வாழ் தவளைகள் கடத்தும் என்று எண்ணி தவளையின்மேல் ஏறிக் கடலைக் கடப்பேன் என்பவனைப்போல், தாரதம்ய ஞானமற்றவர்கள் அறிஞர்களால் அடையத்தக்க ஹரியை அறியாமல் சௌர சைவ மதத்தாரைப் பின்பற்றிக் கெடுகிறார்கள்.",
        '0.20': "அரசகுமாரனாக இருந்து காசுக்குக் கை நீட்டுவதுபோல், வீட்டில் காமதேனு இருக்கையில் சாணத்தை விரும்புவதுபோல், வேணுகானப்ரியனிடம் உலக இன்பத்தைக் கேட்காதே; லக்ஷ்மிநாதனின் திருவடிப் பக்தியைக் கேள், புகழ்.",
        '0.21': "(இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.) பசியால் காட்டுக்குச் சென்று இலந்தைப் பழங்களை எதிர்பார்த்து புதரில் சிக்கி வாய் பிளந்து நின்றவனைப்போல், பிரம்மாவின் தந்தையை வழிபடாமல் உன் வயிற்றுக்காக சாதுக்களின் அடையாளங்களைக் காட்டுபவர்களை ஆராதித்து சம்சாரத்தில் உழலாதே.",
        '0.22': "ஞானம், ஞேயம், ஞாதா என்ற பெயர்களால் புத்தி முதலியவற்றின் அதிஷ்டானத்தில் உறைந்து அந்தந்தப் பெயர்களால் அழைக்கப்படுகிறான். சூரிய மண்டலத்தில் தன்னைக் காட்டி, சுகர், சௌனகர் முதலிய முனிவர்களின் இதய ஆகாயத்தின் சந்திரனான அவன் அவர்களின் வசமாகிறான்.",
        '0.23': "(இப்பாடலின் பாடம் தெளிவற்றது.) தெளிவான பகுதி: காலம் முதலியவற்றின் விதி நிஷேதங்களைப் பார்க்காமல் தினமும் ஹரிசேவை செய்துகொண்டிரு; பக்தவத்ஸலனான அவன் தன் இல்லத்தில் வைத்துக் காக்கிறான்.",
        '0.24': "(முதல் வரிகள் தெளிவற்றவை.) சிவராத்திரி விரதம், துவாதசி, தசமி, பித்ருகர்மங்கள் ஒரே நேரத்தில் கூடும்போது சில நடைமுறைகளை விடுவதுபோல், நிந்தனைக்குரியவர்களிடமிருந்து வந்த செல்வத்தைக் கண் திறந்து பார்க்கவே பார்க்காதே; ஸ்ரீமதானந்ததீர்த்தரின் அந்தர்யாமியான ஹரியை எங்கும் வழிபட்டுக்கொண்டிரு.",
        '0.25': "ஸ்ரீமனோரமன், மேருவைப்போன்றவன், த்ரிககுத்தாமன், நல்ல மங்கல குணங்களில் எல்லையற்றவன், புனிதப் பெயருடையவன், தேவர்களை உயர்த்துபவன் ரகுராமன் அன்புடன் தினமும் தன் மாமகிமைகளைத் துதிப்பவர்களுக்கு, சுதாமனிடம் மகிழ்ந்ததுபோல், எல்லா விருப்பங்களையும் அளிக்கிறான்.",
        '0.26': "பெற்றோரின் அடையாளம் தெரியாத குழந்தை அயல்நாட்டில் தன்னைப்போன்றவர்களின் பெற்றோரைக் கண்டு 'என்னைப் பெற்றவர்களும் இவர்களைப்போல் இருப்பார்கள், நான் அவர்களைக் காண்பேன்' என்று தேடுவதுபோல் அறிஞர்கள் (அடுத்த பாடலில் தொடர்கிறது).",
        '0.27': "புராணத் தொகுப்பிலும் மஹாபாரதத்தின் ஒவ்வொரு சொல்லிலும் அஜிதனின் குணரூபங்களைத் தேடி பேரானந்தத்துடன் அறிவுடையோர் நாள்தோறும் சாரஸ்வத சமுத்திரத்தில் மீனைப்போல் இடைவிடாது உற்சாகத்துடன் சஞ்சரிக்கிறார்கள்.",
        '0.28': "'மன்மதனின் தந்தையே, ஹரியே, ஸ்ரீவத்ஸ அடையாளனே, சரணடைந்தவர்களிடம் வாத்சல்யம் கொண்டவனே, வராரோஹனே, வைகுண்டவாசியே, சித்சுகம் அளிப்பவனே, காப்பாற்று' என்று அழைத்தால், கன்றின் குரலுக்குப் பசு வருவதுபோல் அவன் பேருற்சாகத்துடன் பொறாமையற்றவர்களிடம் வந்து சேருகிறான்.",
        '0.29': "ஞானிகளுக்கு அருகில் இருப்பவன்; தீயொழுக்கத்தினருக்கும் தைத்திய வம்சத்துக்கும் எப்போதும் தொலைவிலும் தொலைவான, அடைவதற்கரியவன். மீண்டும் மீண்டும் நினைப்பவர்களின் சம்சாரம் என்னும் மகாசர்ப்பத்துக்கு சர்ப்பாரியாகி (கருடனாகி) நல்லோருக்கு எப்போதும் நல்ல சுகத்தை அளிக்கிறான்.",
        '0.30': "சக்கரம், சங்கு, கதை, தாமரை ஏந்தியவன், கடக்க முடியாதவன், அடைய அரிய வாசம் உடையவன், பிரம்மா, சிவன், இந்திரன், சூரியன் முதலிய தேவர்களால் வணங்கப்படும் திருவடித்தாமரை உடையவன், அஞ்சாதவன்; சுக்ராசாரியரின் சீடனான பலியின் அசுவமேத முயற்சியைக் கெடுத்து, அண்டத்தைக் கடந்து கங்கையைப் பெற்றவன் த்ரிவிக்ரமன் என்ற பெயரினன்.",
        '0.31': "ஹரியைத் தவிர தேவகணத்தில் அத்தகைய ஆற்றலுடையவர் யாரும் இல்லை; அவனே எல்லோரினும் உயர்ந்தவன். ஆகவே எல்லாக் காலத்திலும் பக்தியுடன், பிற பற்றுகளை விட்டு, ஹரிகதாம்ருத பானத்தில் முழுமையாக ஈடுபட்டிரு.",
        '0.32': "வணங்கியவர்களின் விருப்பங்களை அளிப்பவன், பக்தர்களின் சிந்தாமணி, மணிமயமான ஆபரணங்களால் அலங்கரிக்கப்பட்டவன், முக்குணங்களுக்கு அப்பாற்பட்டவன், ஆழமானவன், சன்மகிமையுள்ளவன், பக்தர்களின் குற்றங்களை எண்ணாதவன், பூமிஜையின் கணவன், சரண்யனான பரமாத்மா சபரி 'ராமார்ப்பணம்' என்று கொடுத்த பழத்தை ஏற்றான்.",
        '0.33': "'இவனை நான் அறிவேன்' என்பவர் இல்லை, 'இவன் வேண்டாம்' என்பவர் இல்லை; உலகில் அவன் இல்லாத இடம் இல்லை; முழுமையாக அறிந்தவர் இல்லை. வெல்லக் கட்டி அச்சுப் பொம்மையைப்போல் எல்லோருக்குள்ளும் இருக்கும் ஸ்ரீபூநாயகனுக்கு நிகர் இல்லை; அவன் உலகுக்கெல்லாம் ஒப்பற்ற மல்லன்.",
        '0.34': "(இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.) சொல்லுக்கு எட்டாதவன், சந்திர வம்சத்தானின் தம்பி, யதுவம்சக் கடலின் சந்திரன், ஒப்பற்றவன், எல்லையற்றவன்; அமைதி அடக்கம் பெற்ற தன் பக்தனுக்கு பிராரப்த கர்மங்களை அனுபவிக்கச் செய்து தீர்த்து, கருணைநிறைந்தவனாய் மூண்ட நெருப்பைப்போல் அவனை விடாமல் இருக்கிறான்.",
        '0.35': "ஸ்ரீ, பிரம்மா முதலிய தேவர்களால் வணங்கப்படும் பிறப்பற்றவன் இந்தப் பூமியில் தேவகி தேவியின் கருவில் மனிதர்களைப்போல் அவதரித்தான்; ரேவதிரமணனின் (பலராமனின்) தம்பியான ஜகந்நாத விட்டலன் தன் திருவடிகளைச் சார்ந்தவர்களைக் காத்து தைத்திய கூட்டங்களை அழித்தான்.",
      },
    },
    'harikathamrutasara-20': {
      summary: "இருபதாம் ஸந்தி (குணதாரதம்யம், குணங்களின்படி ஜீவர்களின் உயர்வு தாழ்வு வரிசை): ஹரியே மிக உயர்ந்தவன்; அவனுக்குப் பின் லக்ஷ்மி, பின் பிரம்மா-வாயு இணை, அவர்களின் மனைவியர் சரஸ்வதி-பாரதி, பின் கருடன், சேஷன், சிவன், இவ்வாறு தேவர்கள், ரிஷிகள், அரசர்கள், மனிதர்கள் வரை குணங்களின் அளவால் அளக்கப்பட்ட வரிசை. ஜீவர்கள் முக்குணங்களின்படியும் வகைப்படுத்தப்படுகிறார்கள்; அவர்களுள் கலி எல்லோரினும் தாழ்ந்தவன். இந்தத் தாரதம்ய ஞானம் முக்தியின் வாயில், சம்சாரக்கடலுக்குப் படகு, வைகுண்டத்துக்குப் படிக்கட்டு என்று கூறப்படுகிறது; தகுதியுள்ளவர்களுக்கே சொல்ல வேண்டும். இவர்கள் அனைவரையும் வரிசையாக வணங்கும் துதியுடன் ஸந்தி முடிகிறது.",
      verses: {
        '0.0': "குருவின் கருணையால் ஹரிகதாம்ருதஸாரத்தைச் சொல்கிறேன்; பரம பகவத்பக்தர்கள் இதை ஆதரவுடன் கேட்க வேண்டும்.",
        '0.1': "ஸ்ரீ துர்கையரின் மனங்கவர்ந்தவனே, பிரம்மா முதலிய தேவகணங்களால் ஆராதிக்கப்படும் திருவடித்தாமரை உடையவனே, உலகின் உள்ளும் புறமும் வியாபித்தவனே, பூதரனே, சேஷனைக் குடையாகக் கொண்டவனே, விலக்குகளுக்கு அப்பாற்பட்டவனே, விசித்திரச் செயல்களுடையவனே, நல்லறிவும் இன்பமும் நிறைந்த உடலுடையவனே, பரம புனிதனே, நல்லொழுக்கனே!",
        '0.2': "நித்யனே, நிர்மலனே, வேதங்களால் அறியப்படுபவனே, படைப்பு, காப்பு, அழிப்புகளுக்கு அப்பாற்பட்டவனே, துதிக்கத்தக்கவனே, பூஜிக்கத்தக்கவனே, புகழ்பெற்றவனே, முக்தர் அமுக்தர் கணங்களால் சேவிக்கப்படுபவனே, சத்தியகாமனே, சரண்யனே, சாசுவதனே, அடியார்மீது அன்புடையவனே, பயம் போக்குபவனே, மிகவும் பிரியமானவனே, ஜகந்நாதனே, என்னைக் காப்பாற்று!",
        '0.3': "(இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.) ரமை பரம புருஷனின் ரூபகுணங்களைப் பின்பற்றி ஓட்டமாகத் தோன்றுகிறாள்; ஒப்பற்றவள், துயரற்றவள், இன்பம் நிறைந்தவள் எனப்படுகிறாள்; ஹரிக்கு மூன்று தாமங்களாகவும் ஆபரணம், ஆடை, ஆயுதங்களாகவும் இருந்து, அக்ஷரை எனப்பட்டு பகைவர்களை அழிக்கிறாள்.",
        '0.4': "அவனைவிட எல்லையற்ற குணங்களில் ஸ்ரீதருணி குறைந்தவள் எனப்படுகிறாள்; நித்தியமுக்தை, மாறாதவள், முக்குணங்களற்றவள்; பாவம் கழுவப்பட்ட பிரம்மா வாயுவின் தாய் எனப்படும் மஹாலக்ஷ்மி ஸ்ருதி புராணங்களில் எப்போதும் புகழ்பெற்றவள்.",
        '0.5': "பிரம்மாவும் வாயுவும் இருவரும் சமமானவர்கள், சமவர்த்திகள்; ருத்ரன் முதலிய தேவகணங்களால் சேவிக்கப்படுபவர்கள், பரப்பிரம்மன் என்ற பெயருடையவர்கள். இந்த இரட்டையரைவிட மஹாலக்ஷ்மி தன் இனக் குணங்களில் கோடி மடங்கு உயர்ந்தவள்; ஆகையால் பிரம்மா வாயுவினர் அளவற்ற பகுதிகளால் தாழ்ந்தவர்கள் எனப்படுகிறார்கள்.",
        '0.6': "(கடைசி வரிகள் தெளிவற்றவை.) அவர்களின் மனைவியர் சரஸ்வதியும் பாரதியும் பலம், ஞானம் முதலிய குணங்களில் தம் கணவர்களைவிட நூறு குணங்கள் குறைந்தவர்கள். வாக்தேவி சிறப்புடையவள்; அவர்களின் பதவியால் அறிஞர்கள் பிரம்மா வாயுவில் ஹரியை நல்ல பக்தியுடன் சிந்திக்க வேண்டும்.",
        '0.7': "(இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.) கருடன், சேஷன், ம்ருடன் ஒருவருக்கொருவர் சமம்; வாணியைவிட நூறு குணங்கள் குறைந்தவர்; இம்மூவருள் சேஷபதத்தால் அவன் மிக்கவன் எனப்படுகிறான். மேனகையின் மகள் பார்வதி வாருணி, சௌபர்ணியைவிட இரண்டு குணங்கள் அதிகம்.",
        '0.8': "(இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.) கருடன், சேஷன், மகேசன் ஆகியோரின் மனைவியர் சௌபர்ணி, வாருணி, பார்வதி மூவரும் பத்து குணங்கள் குறைந்தவர்; ஹரனின் மனைவி கௌரியைவிட இந்திரனும் காமனும் பத்து குணங்களில் குறைந்தவர்; இந்திரனைவிட மன்மதன் பதவியால் குறைந்தவன்.",
        '0.9': "(இப்பாடலின் பாடம் தெளிவற்றது.) பத்து, ஐந்து குணங்கள் குறைவு என்ற அளவில் வரிசையைக் கீழே தொடர்ந்து அஹங்காரிக ப்ராணன், காமனின் பரிவாரம், அநிருத்தன் (அஹங்காரத்தின் அபிமானி), ரதி, மனு, தக்ஷன், குரு (பிருஹஸ்பதி), சசி, ப்ரவஹன் ஆகியோரைக் குறிப்பிடுகிறது.",
        '0.10': "(இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.) ப்ரவஹனைவிட இரண்டு குணங்கள் குறைந்தவர்கள் சூரியன், சந்திரன், யமன், ஸ்வாயம்புவ மனு, அவன் மனைவி சதரூபை ஆகிய நால்வர்; அவர்களைவிட கால், அரைக்கால் குணம் குறைந்தவர்கள் நாரதர், பிருகு, அக்னி, பிரசூதி எனப்படுகிறார்கள்.",
        '0.11': "(இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.) தாரதம்யப் பட்டியல் தொடர்கிறது: அக்னியைவிட இரண்டு குணங்கள் குறைந்தவர்கள் பிரம்மாவின் புதல்வர் மரீசி முதலியோர்; வைவஸ்வத மனுவும் விசுவாமித்திரரும் சற்றுக் குறைந்தவர்; பின் நிர்ருதி, தாரை முதலியோர், குபேரனும் விஷ்வக்சேனனும் அவர்களைவிடவும் சற்றுக் குறைந்தவர்.",
        '0.12': "(இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.) குபேரன், விஷ்வக்சேனன், கௌரிபுத்திரர்களுக்கு மேற்கூறிய பிறர் சமமானவர் எனப்படுகிறார்கள்; ஆதித்யர், நாற்பத்தேழு மருத்துக்கள், வசுக்கள், ருத்ரர்கள், விஸ்வேதேவர், இரு அசுவினிகள், பித்ருக்கள், பூமிதேவி முதலிய கணங்கள் அதே நிலையில் பட்டியலிடப்படுகின்றன.",
        '0.13': "இவர்களைவிடக் குறைந்தவர்கள்: ச்யவனர், சனகாதியர், கவி, ஜயந்தன், கசியபர், பதினொரு மனுக்கள்; துருவன், நகுஷன், சசிபிந்து, ஹைஹயன், துஷ்யந்தன்; விரோசனனின் மகன் பலி முதலிய ஏழு இந்திரர்கள்; ககுத்ஸ்தன், கயன்.",
        '0.14': "பிருது, பரதன், மாந்தாதா, பிரியவிரதன், மருத்தன், பிரகலாதன், பரீக்ஷித், ஹரிச்சந்திரன், அம்பரீஷன், உத்தானபாதன் முதலிய நூறு புண்ணியசீலர்கள் கதாதரனின் ஆதரவுடையவர்கள். இவர்கள் பிரியவிரதனைவிட இரண்டு குணங்கள் குறைந்தவர்கள், 'கர்மஜர்' (செயலால் தேவத்தன்மை பெற்றவர்) எனப்படுகிறார்கள்.",
        '0.15': "(இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.) இன்னும் கீழே நளினி, சஞ்ஜ்ஞை, ரோஹிணி, ஷ்யாமலை, விராட், பர்ஜன்யன்; அக்னியின் மனைவி இரண்டு குணங்கள் குறைந்தவள்; பின் கங்கை, புதன் இரண்டு குணங்கள் கீழ்; பின் உஷை, சனைச்சரன் இன்னும் கீழ்.",
        '0.16': "(இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.) கர்மாதிபதி புஷ்கரன் இரண்டு குணங்கள் குறைந்தவன்; ஆஜானஜ தேவர்களும் நீண்டாயுள் பித்ருக்களும் கிங்கரர்களையும் புஷ்கரனையும்விட உயர்ந்தவர்கள்; இந்திர சபையின் பாடகர்களில் சிறந்த தும்புரு முதலியோர் பத்து குணங்கள் குறைந்தவர்; ஒன்பது கோடி ரிஷிகள் (நூறு பேரைத் தவிர) தும்புருவுக்குச் சமம்.",
        '0.17': "(இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.) அவரவர் மனைவியரும் அப்சரப் பெண்களும் (சிறந்தவர்களைத் தவிர) சமம்; மனுஜ கந்தர்வர்கள் பன்னிரண்டு குணங்கள் குறைந்தவர்; அரசர்கள் பத்து குணங்கள்; பெண்கள் சிறந்த மனிதர்களைவிட நூறு குணங்கள் குறைந்தவர்கள்.",
        '0.18': "(இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.) முக்குணங்களின்படி ஜீவர்கள் ஒன்பது வகைகளாகின்றனர். சத்வமுடையவர் மேல் மூன்று வகை; ரஜஸ்-சத்வ அதிகாரிகள் பகவத்பக்தர் எனப்படுகிறார்கள். நித்தியபத்தர்களான ரஜோ-ரஜஸ்சினர் பூமி, சொர்க்கம், நரகத்தில் பிறந்து பூமியில் சஞ்சரிக்கிறார்கள்; பின் ரஜஸ்-தமஸ்சினர்.",
        '0.19': "(பாடலின் முடிவு முழுமையற்றது.) பின் தமஸ்-சாத்விகர் எனப்படுவோர்; எண்ணற்ற பெயருடைய அசுரகணங்கள் தமோ-ராஜஸர் எனப்படுகிறார்கள், தைத்திய சமூகம்; தமஸ்-தாமஸர் கலியும் அவன் மனைவியும்; அதமர்களில் அதமாதமன் தீயாத்மா கலி என்று அழைக்கப்படுகிறான்.",
        '0.20': "மூவுலகிலும் இவனைப்போன்ற பாவி ஜீவன் இல்லை; ஒன்பது வகை வெறுப்புகளுக்கு உறைவிடம் எனப்படுகிறான். போர், பொன், நடனப்பெண், இளம்பெண், சூதாட்டம், மது, பொய் ஆகியவற்றில் மயக்கம் மூட்டி மக்களைக் கெடுக்கிறான் என்று அறிந்து இவற்றைத் துறக்க வேண்டும்.",
        '0.21': "(இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.) மூவகை ஜீவர்களின் வரிசையைப் படைத்து கருணைக்கடல் தன் மனைவியருடன் விளையாடுகிறான். தேவர் அசுரர்களின் தாரதம்ய விவரத்தை அறிந்த மகாத்மாக்களிடம் மகிழ்ந்து அவர்களை சம்சாரத்திலிருந்து கரையேற்றுகிறான்.",
        '0.22': "தேவர் தைத்தியர்களின் தாரதம்யம் பாவமானி (மத்வரின்) மதத்தைப் பின்பற்றுபவர்களுக்கு மிக அவசியமானது; எல்லாக் காலத்திலும் அறிய வேண்டும். இது பாவக்காட்டுக்குக் காட்டுத்தீ, சம்சாரக்கடலுக்குப் புதுப் படகு, வைகுண்ட உலகுக்குப் படிக்கட்டு என்று அழைக்கப்படுகிறது.",
        '0.23': "தாரதம்ய ஞானம் பக்தர்களுக்கு முக்தியின் வாயில்; அறிஞர்கள் இதைக் காட்டிச் சொல்லி இன்பக்கடலில் திளைக்கிறார்கள். கொடிய மனிதர்களுக்கு இது காதுக்குக் கடுமையானது. தவறான வாதிகளை விட்டு தகுதியுள்ளவர்களுக்கு இதை நாளும் தெரிவிக்க வேண்டும்.",
        '0.24': "(இங்கிருந்து பெயர்களின் துதிமாலை தொடங்கி அடுத்த இரண்டு பாடல்களில் தொடர்கிறது.) ஹரி, ஸ்ரீ, பிரம்மா, வாயு, பாரதி, கருடன், சேஷன், ஷண்மஹிஷிகள், கிரிஜை, இந்திரன், காமன், பிராணன், அநிருத்தன், சசி, குரு, ரதி, மனு, தக்ஷன், ப்ரவஹ மருத், மானவி, யமன், சந்திரன், சூரியன், வருணன், நாரதர், அக்னி, பிரசூதி, பிருகு முனி...",
        '0.25': "...பிரம்மாவின் புதல்வர்கள் மரீசி முதலிய விரதிவரர்கள், வைவஸ்வதன், தாரை, மித்திரன், நிர்ருதி, ப்ரவஹ மாருதனின் மனைவி, தனேசன் (குபேரன்), அசுவினிகள், கணபதி (விஷ்வக்சேனன்), சேஷனின் நூறு பேர், மனுக்கள், உசித்யர், ச்யவன முனிவர்கள் இவர்கள் அனைவருக்கும் வணங்குகிறேன்.",
        '0.26': "புண்ணியசீலர்களான நூறு அரசர்களை வணங்குகிறேன். பாகீரதி, விராட், பர்ஜன்யன், ரோஹிணி, ஷ்யாமலா, சஞ்ஜ்ஞை, அக்னியின் மனைவி, புதன், உஷை, க்ஷிதி (பூமிதேவி), சனைச்சரன், புஷ்கரன் ஆகியோரை வணங்கி, 'பக்தியும் ஞானமும் அருளட்டும்' என்று வேண்டுகிறேன்.",
        '0.27': "நந்தகோபகுமாரனின் பதினாறாயிரத்து நூறு மனைவியர், அகஸ்தியர் முதலிய முனிவர்கள், ஊர்வசி முதலிய அப்சரப் பெண்கள், நூறு தும்புருக்கள் என்னைக்கொண்டு கம்சாரியின் குணங்களைக் கீர்த்தனம் செய்விக்கட்டும்.",
        '0.28': "புனிதர்களான சுசி, சுத்த என்ற தேவர்கள், ஆஜானஜர்கள், சிரபித்ருதேவர்கள், நரகந்தர்வர்கள், அரசர்கள், மனிதரில் சிறந்தவர்கள் இவர்கள் இந்தப் பூமியிலுள்ள வைஷ்ணவர்களின் வரிசையில் உள்ளவர்கள் என்று அறிந்து நாளும் மகிழ்ச்சியுடன் எல்லாவகையிலும் சேவிக்க வேண்டும்.",
        '0.29': "மனிதரில் சிறந்தோர் முதல் நான்முகப் பிரம்மா வரையிலான நூறு நிலைகளின் உயர்வை வரிசையாகச் சிந்திக்கும் பக்தர்களுக்கு ஸ்ரீநிதி ஜகந்நாத விட்டலன் தானே மகிழ்ந்து நான்கு புருஷார்த்தங்களையும் அளிக்கிறான். அறிஞர்கள் இதை மறவாமல் அன்புடன் இடைவிடாது படிக்க வேண்டும்.",
      },
    },
  },
};
